window.QBANK = window.QBANK || {};
window.QBANK["sma-informatika"] = {
  level: "SMA", subject: "Informatika", duration: 900,
  questions: [
    { q: "Dalam Informatika, yang dimaksud dengan algoritma adalah …", options: ["Kumpulan perangkat keras komputer", "Bahasa pemrograman tingkat tinggi", "Urutan langkah-langkah logis yang pasti untuk menyelesaikan suatu masalah", "Diagram alir berbentuk simbol-simbol"], answer: 2, solution: "1. Algoritma adalah inti dari pemecahan masalah komputasional. 2. Ciri utamanya: urutan langkah yang jelas, logis, dan berhingga (pasti selesai). 3. Perangkat keras dan bahasa pemrograman hanyalah alat bantu, sedangkan flowchart hanya salah satu cara menggambarkannya." },
    { q: "Pada flowchart, simbol belah ketupat (diamond) digunakan untuk menyatakan …", options: ["Keputusan atau percabangan", "Awal atau akhir program", "Proses perhitungan", "Input atau output data"], answer: 0, solution: "1. Ingat simbol standar flowchart: oval = terminator (mulai/selesai), jajar genjang = input/output, persegi panjang = proses. 2. Belah ketupat = decision, yaitu titik keputusan dengan dua cabang ya/tidak. 3. Jadi simbol tersebut menyatakan keputusan atau percabangan." },
    { q: "Perhatikan program berikut. for i in range(1,4): print(i*2). Output yang dihasilkan adalah …", options: ["1, 2, 3", "2, 4, 6", "2, 4, 6, 8", "0, 2, 4"], answer: 1, solution: "1. range(1,4) menghasilkan nilai i = 1, 2, 3 (angka 4 tidak ikut). 2. Setiap nilai i dikalikan 2: 1x2=2, 2x2=4, 3x2=6. 3. Jadi output yang tercetak adalah 2, 4, 6." },
    { q: "Perhatikan program berikut. x = 1. while x < 8: x = x * 2. Lalu print(x). Nilai x yang dicetak adalah …", options: ["4", "16", "7", "8"], answer: 3, solution: "1. Telusuri loop: x=1, karena 1<8 maka x menjadi 2. 2. x=2, karena 2<8 maka x menjadi 4. 3. x=4, karena 4<8 maka x menjadi 8. 4. Sekarang 8<8 bernilai salah, loop berhenti, sehingga yang dicetak adalah 8." },
    { q: "nilai = 75. if nilai >= 90: print(A) elif nilai >= 75: print(B) else: print(C). Huruf yang tercetak adalah …", options: ["A", "C", "B", "Terjadi error"], answer: 2, solution: "1. Cek kondisi pertama: 75 >= 90? Salah, lewati. 2. Cek kondisi kedua: 75 >= 75? Benar, maka cetak B. 3. Cabang else tidak dieksekusi karena sudah ada satu kondisi yang terpenuhi." },
    { q: "for i in range(2): for j in range(3): print(i, j). Urutan output yang benar adalah …", options: ["0 0, 0 1, 0 2, 1 0, 1 1, 1 2", "0 0, 1 0, 0 1, 1 1, 0 2, 1 2", "0 0, 0 1, 1 0, 1 1, 2 0, 2 1", "1 1, 1 2, 1 3, 2 1, 2 2, 2 3"], answer: 0, solution: "1. Loop luar berjalan untuk i = 0, lalu i = 1. 2. Untuk setiap nilai i, loop dalam j = 0, 1, 2 berjalan sampai tuntas. 3. Saat i=0 dihasilkan (0,0),(0,1),(0,2); saat i=1 dihasilkan (1,0),(1,1),(1,2)." },
    { q: "Manakah berikut ini yang bertipe data float (bilangan desimal)?", options: ["halo", "3.14", "2026", "True"], answer: 1, solution: "1. Teks dalam tanda kutip adalah string, termasuk 2026 yang diapit kutip. 2. True adalah tipe boolean. 3. 3.14 tanpa tanda kutip dan mengandung titik desimal adalah float." },
    { q: "Bilangan biner 1011 jika diubah ke desimal adalah …", options: ["9", "10", "11", "13"], answer: 2, solution: "1. Tulis bobot tiap posisi dari kanan: 1, 2, 4, 8. 2. Kalikan dengan bitnya: 1x1 + 1x2 + 0x4 + 1x8 = 1 + 2 + 0 + 8. 3. Hasil penjumlahannya adalah 11." },
    { q: "Hasil dari 17 % 5 (17 modulo 5) adalah …", options: ["3", "4", "2", "1"], answer: 3, solution: "1. Operator % menghasilkan sisa hasil pembagian. 2. 17 dibagi 5 sama dengan 3 sisa 2 (karena 3x5=15, sisa 17-15=2). 3. Jadi 17 % 5 = 2." },
    { q: "Struktur perulangan (looping) paling tepat digunakan ketika …", options: ["Suatu perintah harus dijalankan berulang kali", "Program hanya berjalan sekali", "Terjadi kesalahan sintaks", "Data harus dihapus permanen"], answer: 0, solution: "1. Perulangan berfungsi mengulang satu blok perintah tanpa menulisnya berkali-kali. 2. Contoh: mencetak angka 1 sampai 100 atau menjumlahkan banyak data. 3. Pilihan lain tidak berkaitan dengan pengulangan perintah." },
    { q: "Dalam pemrograman, konstanta berbeda dari variabel karena …", options: ["Nilainya bisa diubah kapan saja", "Hanya bisa menyimpan teks", "Hanya dipakai di dalam loop", "Nilainya tetap dan tidak boleh diubah selama program berjalan"], answer: 3, solution: "1. Variabel adalah wadah yang isinya boleh berubah-ubah. 2. Konstanta dikunci nilainya sejak didefinisikan, misalnya PI = 3.14. 3. Mencoba mengubah konstanta akan menimbulkan error atau perilaku tak terduga." },
    { q: "Untuk mencari sebuah nama dalam daftar 1000 nama yang belum terurut, algoritma pencarian yang tepat adalah …", options: ["Binary search", "Linear search", "Bubble sort", "Rekursi faktorial"], answer: 2, solution: "1. Binary search mensyaratkan data sudah terurut, sehingga tidak bisa dipakai di sini. 2. Linear search memeriksa satu per satu dari awal sampai ketemu, cocok untuk data acak. 3. Bubble sort adalah algoritma pengurutan, bukan pencarian." },
    { q: "data = [apel, mangga, jeruk]. Nilai dari data[1] adalah …", options: ["apel", "mangga", "jeruk", "Error karena indeks mulai dari 1"], answer: 1, solution: "1. Indeks array dimulai dari 0, bukan 1. 2. Maka data[0]=apel, data[1]=mangga, data[2]=jeruk. 3. Jadi data[1] bernilai mangga." },
    { q: "Ke dalam sebuah stack dilakukan push 5, lalu push 3, lalu push 8. Kemudian dilakukan pop dua kali. Dua nilai yang keluar secara berurutan adalah …", options: ["5 lalu 3", "3 lalu 8", "5 lalu 8", "8 lalu 3"], answer: 3, solution: "1. Stack bersifat LIFO: yang terakhir masuk, pertama keluar. 2. Susunan tumpukan dari bawah: 5, 3, 8 dengan 8 paling atas. 3. Pop pertama mengeluarkan 8, pop kedua mengeluarkan 3." },
    { q: "Ke dalam sebuah queue dilakukan enqueue A, lalu B, lalu C. Kemudian dilakukan dequeue satu kali. Nilai yang keluar adalah …", options: ["A", "C", "B", "Ketiganya sekaligus"], answer: 0, solution: "1. Queue bersifat FIFO: yang pertama masuk, pertama keluar. 2. Urutan antrean: A paling depan, diikuti B, lalu C. 3. Dequeue mengeluarkan yang paling depan, yaitu A." },
    { q: "Contoh penerapan struktur data stack dalam penggunaan komputer sehari-hari adalah …", options: ["Antrean printer", "Daftar belanja", "Tombol back pada browser", "Jadwal keberangkatan kereta"], answer: 2, solution: "1. Tombol back membuka halaman yang terakhir dikunjungi, persis perilaku LIFO. 2. Antrean printer dan jadwal kereta bersifat FIFO sehingga memakai queue. 3. Jadi penerapan stack yang tepat adalah tombol back browser." },
    { q: "Antrean dokumen pada printer paling tepat dimodelkan dengan struktur data …", options: ["Stack", "Queue", "Tree", "Graph"], answer: 1, solution: "1. Dokumen yang datang duluan harus dicetak duluan agar adil dan berurutan. 2. Itu adalah perilaku FIFO yang dimiliki queue. 3. Stack justru mencetak dokumen terakhir duluan sehingga tidak adil." },
    { q: "Setiap node pada linked list umumnya menyimpan …", options: ["Data dan pointer ke node berikutnya", "Hanya angka indeks", "Data dan seluruh isi list", "Nama variabel saja"], answer: 0, solution: "1. Node adalah unit terkecil penyusun linked list. 2. Ia menyimpan data plus alamat (pointer) ke node berikutnya agar rantai tersambung. 3. Tanpa pointer, node-node tidak dapat dirangkai menjadi satu list." },
    { q: "Node pertama pada sebuah linked list disebut …", options: ["Tail", "Leaf", "Root", "Head"], answer: 3, solution: "1. Untuk mengakses linked list kita membutuhkan pintu masuk berupa node pertama. 2. Node pertama ini dinamakan head, sedangkan node terakhir disebut tail. 3. Root dan leaf adalah istilah untuk struktur tree, bukan linked list." },
    { q: "Kelebihan utama array dibanding linked list adalah …", options: ["Mudah disisipi di tengah", "Ukuran selalu dinamis", "Akses elemen lewat indeks sangat cepat", "Tidak butuh memori"], answer: 2, solution: "1. Elemen array tersimpan berurutan di memori sehingga alamat data[i] dapat dihitung langsung. 2. Linked list harus menelusuri node satu per satu mulai dari head. 3. Penyisipan justru lebih mudah di linked list karena tidak perlu menggeser elemen." },
    { q: "Syarat utama sebuah kolom menjadi primary key adalah …", options: ["Boleh kosong asalkan unik", "Nilainya unik dan tidak boleh kosong", "Harus berupa angka", "Harus ada di semua tabel lain"], answer: 1, solution: "1. Primary key adalah identitas tiap baris, misalnya NIS siswa. 2. Dua baris tidak boleh memiliki identitas yang sama (unik) dan tidak boleh tanpa identitas (not null). 3. Tipe datanya bebas, tidak harus berupa angka." },
    { q: "Perintah SQL yang benar untuk menampilkan kolom nama dan nilai dari tabel siswa adalah …", options: ["SELECT nama, nilai FROM siswa;", "GET nama, nilai IN siswa;", "SHOW nama, nilai TABLE siswa;", "READ nama, nilai FROM siswa;"], answer: 0, solution: "1. Sintaks dasar SQL: SELECT kolom FROM tabel. 2. Kolom yang diinginkan ditulis setelah SELECT dan dipisah koma. 3. GET, SHOW, dan READ bukan perintah standar untuk menampilkan data." },
    { q: "SELECT * FROM siswa WHERE kelas = 'X-1'; Klausa WHERE pada perintah tersebut berfungsi untuk …", options: ["Mengurutkan hasil", "Menghapus tabel", "Menyaring baris yang memenuhi syarat", "Menambah kolom baru"], answer: 2, solution: "1. WHERE adalah filter baris berdasarkan kondisi tertentu. 2. Di sini hanya baris dengan kelas = X-1 yang ditampilkan. 3. Pengurutan memakai ORDER BY, bukan WHERE." },
    { q: "Perintah SQL yang benar untuk menambah data siswa bernama Budi kelas X-1 adalah …", options: ["ADD siswa (nama, kelas) = ('Budi','X-1');", "INSERT siswa SET nama='Budi';", "UPDATE siswa (nama, kelas) VALUES ('Budi','X-1');", "INSERT INTO siswa (nama, kelas) VALUES ('Budi','X-1');"], answer: 3, solution: "1. Perintah menambah baris baru adalah INSERT INTO. 2. Formatnya: INSERT INTO tabel (kolom) VALUES (nilai). 3. UPDATE dipakai untuk mengubah data lama, bukan menambah data baru." },
    { q: "Dalam sebuah tabel basis data, satu baris data (misalnya data satu orang siswa) disebut …", options: ["Field", "Record", "Atribut", "Skema"], answer: 1, solution: "1. Kolom disebut field atau atribut, misalnya nama dan kelas. 2. Baris disebut record (atau tuple), berisi satu kesatuan data utuh. 3. Skema adalah rancangan struktur tabel, bukan isi baris." },
    { q: "Foreign key pada tabel nilai yang merujuk ke tabel siswa berfungsi untuk …", options: ["Menghubungkan tiap nilai dengan data siswa pemiliknya", "Menghapus data siswa secara otomatis", "Mengenkripsi kolom nilai", "Menggandakan tabel siswa"], answer: 0, solution: "1. Foreign key adalah kolom yang nilainya merujuk ke primary key tabel lain. 2. Ini menjaga relasi: setiap nilai terhubung ke siswa yang valid. 3. Tanpanya, bisa muncul nilai milik siswa yang tidak ada datanya." },
    { q: "Mengapa perintah DELETE sebaiknya selalu disertai WHERE? …", options: ["Agar perintah berjalan lebih lambat", "WHERE mempercepat koneksi internet", "Tanpa WHERE, seluruh baris tabel akan terhapus", "Tanpa WHERE perintah tidak bisa dijalankan"], answer: 2, solution: "1. DELETE FROM siswa; tanpa filter akan menghapus semua baris tabel. 2. WHERE membatasi hanya baris tertentu, misalnya WHERE id = 5. 3. Lupa menulis WHERE adalah kesalahan fatal yang umum terjadi." },
    { q: "Pada topologi star, seluruh komputer terhubung ke …", options: ["Satu sama lain secara langsung", "Satu perangkat pusat seperti switch", "Dua kabel backbone", "Satelit komunikasi"], answer: 1, solution: "1. Star berarti bintang: semua node menjadi kaki-kaki yang bertemu di satu titik pusat. 2. Titik pusatnya adalah switch atau hub. 3. Kelemahannya: jika perangkat pusat mati, seluruh jaringan ikut mati." },
    { q: "Perangkat yang menghubungkan jaringan LAN sekolah ke internet (jaringan yang berbeda) adalah …", options: ["Hub", "Switch", "Kabel UTP", "Router"], answer: 3, solution: "1. Switch dan hub hanya menghubungkan perangkat di dalam satu jaringan lokal. 2. Router meneruskan paket antar jaringan yang berbeda sekaligus memilih jalur terbaik. 3. Jadi penghubung LAN ke internet adalah router." },
    { q: "Perbedaan utama hub dan switch adalah …", options: ["Hub meneruskan data ke semua port, switch hanya ke port tujuan", "Switch lebih lambat dari hub", "Hub bisa menghubungkan ke internet", "Tidak ada perbedaan sama sekali"], answer: 0, solution: "1. Hub bekerja secara buta: data yang masuk disebar ke semua port (broadcast). 2. Switch lebih pintar: ia mengingat alamat MAC tiap port dan mengirim hanya ke port tujuan. 3. Akibatnya switch lebih cepat dan lebih aman." },
    { q: "Alamat IPv4 terdiri dari …", options: ["16 bit", "64 bit", "32 bit", "128 bit"], answer: 2, solution: "1. IPv4 ditulis sebagai 4 kelompok angka 0-255, misalnya 192.168.1.1. 2. Setiap kelompok 8 bit, sehingga totalnya 4x8 = 32 bit. 3. Yang 128 bit adalah IPv6, bukan IPv4." },
    { q: "Sebuah jaringan memakai subnet mask 255.255.255.0 (/24). Jumlah alamat IP yang bisa dipakai untuk host adalah …", options: ["256", "24", "510", "254"], answer: 3, solution: "1. Oktet terakhir (8 bit) adalah bagian host: 2 pangkat 8 = 256 alamat. 2. Alamat pertama dipakai untuk network ID dan alamat terakhir untuk broadcast, keduanya tidak bisa dipakai host. 3. Maka 256 - 2 = 254 alamat host." },
    { q: "Perbedaan LAN dan WAN yang paling tepat adalah …", options: ["LAN mencakup area terbatas seperti satu gedung, WAN mencakup area luas antar kota atau negara", "LAN selalu nirkabel, WAN selalu berkabel", "LAN lebih lambat dari WAN", "WAN tidak membutuhkan router"], answer: 0, solution: "1. LAN (Local Area Network): area kecil, misalnya lab komputer sekolah. 2. WAN (Wide Area Network): area luas, misalnya jaringan antar cabang bank; internet adalah WAN terbesar. 3. Kecepatan dan media kabel bukan pembeda utama keduanya." },
    { q: "Dalam model OSI/TCP-IP, protokol HTTP yang dipakai browser bekerja pada layer …", options: ["Network", "Data link", "Fisik", "Aplikasi"], answer: 3, solution: "1. HTTP mengatur komunikasi aplikasi web berupa request dan response halaman. 2. Layer aplikasi adalah layer teratas yang langsung melayani program pengguna. 3. Layer network mengurus alamat IP, sedangkan layer fisik mengurus kabel dan sinyal." },
    { q: "TCP lebih andal dibanding UDP untuk transfer file karena …", options: ["TCP lebih cepat", "TCP memeriksa dan mengirim ulang paket yang hilang", "TCP tidak butuh alamat IP", "UDP hanya untuk video"], answer: 1, solution: "1. TCP memakai acknowledgement: penerima mengonfirmasi setiap paket yang diterima. 2. Paket yang hilang akan dikirim ulang sehingga file sampai utuh. 3. UDP tanpa konfirmasi sehingga lebih cepat, cocok untuk live streaming." },
    { q: "Fungsi utama DNS (Domain Name System) adalah …", options: ["Mengamankan password", "Mempercepat prosesor", "Membagi bandwidth", "Menerjemahkan nama domain menjadi alamat IP"], answer: 3, solution: "1. Manusia mudah mengingat nama seperti google.com, sedangkan komputer memakai alamat IP. 2. DNS adalah buku telepon internet yang memetakan nama domain ke alamat IP. 3. Tanpa DNS kita harus menghafal angka IP setiap situs." },
    { q: "Jenis malware yang dapat menyebar sendiri ke komputer lain tanpa menempel pada program inang adalah …", options: ["Virus", "Trojan", "Worm", "Spyware"], answer: 2, solution: "1. Virus membutuhkan program inang dan aksi pengguna untuk menyebar. 2. Worm bersifat mandiri: menggandakan diri dan menyebar lewat jaringan dengan sendirinya. 3. Trojan menyamar sebagai aplikasi berguna, sedangkan spyware mengintai diam-diam." },
    { q: "Trojan horse disebut demikian karena …", options: ["Menyamar sebagai program yang tampak berguna padahal berbahaya", "Menyebar lewat jasa kuda pos", "Hanya menyerang peternakan", "Berbentuk ikon kuda"], answer: 0, solution: "1. Seperti kisah kuda Troya: tampak sebagai hadiah, ternyata berisi musuh di dalamnya. 2. Trojan tampak seperti game atau aplikasi gratis padahal berisi malware. 3. Ia tidak menggandakan diri seperti virus atau worm." },
    { q: "Ransomware berbahaya karena …", options: ["Menghapus antivirus", "Mengenkripsi data korban lalu meminta tebusan", "Mematikan listrik komputer", "Mencuri kuota internet"], answer: 1, solution: "1. Ransomware mengunci file korban dengan enkripsi yang kuat. 2. Korban diminta membayar tebusan (ransom) untuk mendapatkan kunci pembuka. 3. Membayar pun tidak menjamin data kembali, sehingga backup rutin sangat penting." },
    { q: "Email yang mengaku dari bank dan meminta korban mengklik tautan untuk memasukkan PIN adalah contoh …", options: ["Spam biasa", "Phishing", "Firewall", "Captcha"], answer: 3, solution: "1. Phishing artinya memancing: pelaku menyamar sebagai pihak yang tepercaya. 2. Tujuannya mencuri kredensial lewat situs palsu yang mirip dengan aslinya. 3. Bank asli tidak pernah meminta PIN lewat email." },
    { q: "Password yang paling kuat di antara pilihan berikut adalah …", options: ["12345678", "namasaya", "P@ssw0rd!2026", "tanggallahir"], answer: 2, solution: "1. Password kuat itu panjang, acak, dan mencampur huruf besar-kecil, angka, dan simbol. 2. Urutan angka, nama, dan tanggal lahir mudah ditebak atau dibobol brute force. 3. P@ssw0rd!2026 memenuhi semua kriteria tersebut." },
    { q: "Enkripsi pada dasarnya adalah proses …", options: ["Mengubah data menjadi kode rahasia agar hanya pemilik kunci yang bisa membaca", "Menghapus data secara permanen", "Mempercepat pengiriman data", "Menggandakan data cadangan"], answer: 0, solution: "1. Plaintext diubah menjadi ciphertext memakai algoritma dan kunci. 2. Tanpa kunci yang tepat, ciphertext tidak bisa dibaca. 3. Contohnya pesan WhatsApp yang terenkripsi ujung-ke-ujung." },
    { q: "Manfaat utama Two-Factor Authentication (2FA) adalah …", options: ["Mempercepat login", "Menambah lapisan verifikasi selain password", "Menghilangkan kebutuhan password", "Memperbesar kapasitas penyimpanan"], answer: 1, solution: "1. 2FA meminta bukti kedua, misalnya kode OTP dari HP pemilik akun. 2. Jika password bocor, pelaku tetap terkunci karena tidak punya HP korban. 3. Ini adalah lapisan tambahan, bukan pengganti password." },
    { q: "Machine learning dapat dijelaskan secara sederhana sebagai …", options: ["Komputer yang bisa berpikir seperti manusia sepenuhnya", "Program yang ditulis baris per baris tanpa data", "Kemampuan komputer belajar pola dari data untuk membuat prediksi", "Robot yang bisa berjalan sendiri"], answer: 2, solution: "1. Alih-alih aturan ditulis manual, model dilatih dengan banyak contoh data. 2. Dari data tersebut ia menemukan pola, lalu memprediksi data baru. 3. Contohnya filter spam yang belajar dari ribuan contoh email." },
    { q: "Dalam machine learning, data latih (training data) berfungsi untuk …", options: ["Mengajari model mengenali pola sebelum dipakai", "Menguji kecepatan prosesor", "Menyimpan password pengguna", "Menghapus model lama"], answer: 0, solution: "1. Model ibarat siswa, sedangkan data latih adalah buku latihannya. 2. Semakin banyak dan berkualitas data latih, semakin akurat pola yang ditemukan. 3. Data uji yang terpisah dipakai belakangan untuk menilai performa." },
    { q: "Berikut ini yang merupakan contoh penerapan machine learning adalah …", options: ["Kalkulator penjumlahan", "Sistem rekomendasi film di aplikasi streaming", "Lampu yang dinyalakan saklar", "Jam dinding analog"], answer: 1, solution: "1. Sistem rekomendasi belajar dari riwayat tontonan jutaan pengguna. 2. Ia memprediksi film yang mungkin disukai tiap pengguna. 3. Kalkulator, saklar, dan jam analog memakai aturan tetap, bukan belajar dari data." },
    { q: "Sebuah AI rekrutmen menolak pelamar dari daerah tertentu karena data latihnya bias. Masalah etis utama di sini adalah …", options: ["AI bekerja terlalu cepat", "Keputusan AI tidak adil akibat bias data", "Biaya listrik AI terlalu mahal", "AI tidak bisa berbahasa daerah"], answer: 1, solution: "1. AI meniru pola dari data latih, termasuk prasangka yang ada di dalamnya. 2. Hasilnya adalah diskriminasi sistematis terhadap kelompok tertentu. 3. Etika AI menuntut data yang seimbang serta audit keadilan secara berkala." },
    { q: "Langkah paling tepat saat menerima berita mencurigakan di grup chat adalah …", options: ["Langsung diteruskan agar viral", "Menghapus aplikasi chat", "Membalasnya dengan emosi", "Memeriksa kebenarannya ke sumber tepercaya sebelum membagikan"], answer: 3, solution: "1. Meneruskan tanpa memeriksa berarti ikut menyebarkan hoaks. 2. Verifikasi dulu: cek situs resmi, media kredibel, atau situs cek fakta. 3. Literasi digital berarti saring sebelum sharing." },
    { q: "Jejak digital disebut permanen karena …", options: ["Data yang pernah diunggah sulit dihapus total dari internet", "Internet tidak pernah mati listrik", "Semua orang punya akun media sosial", "Foto selalu tersimpan di HP"], answer: 0, solution: "1. Unggahan bisa disalin, di-screenshot, dan diarsipkan oleh pihak lain. 2. Tombol hapus tidak menarik kembali salinan yang sudah menyebar. 3. Karena itu berpikirlah matang sebelum mengunggah sesuatu." },
    { q: "Deepfake yang meniru wajah dan suara tokoh terkenal untuk menipu adalah contoh …", options: ["Kreativitas positif AI", "Dampak negatif AI yang merugikan", "Kegagalan koneksi internet", "Jenis antivirus baru"], answer: 1, solution: "1. Deepfake memakai AI untuk memalsukan video atau audio secara sangat meyakinkan. 2. Disalahgunakan untuk penipuan, fitnah, dan penyebaran hoaks. 3. Ini sisi gelap AI: teknologinya netral, dampaknya tergantung siapa yang memakai." },
    { q: "Perhatikan pseudocode berikut. total ← 0. FOR i ← 1 TO 5 DO total ← total + i. ENDFOR. PRINT total. Nilai yang dicetak adalah …", options: ["5", "15", "10", "20"], answer: 1, solution: "1. Telusuri loop: i=1 → total=1; i=2 → total=3; i=3 → total=6; i=4 → total=10; i=5 → total=15. 2. Ini adalah penjumlahan 1+2+3+4+5. 3. Jadi nilai yang dicetak adalah 15." },
    { q: "Perhatikan pseudocode berikut. x ← 4. y ← 7. temp ← x. x ← y. y ← temp. PRINT x + y. Hasil yang dicetak adalah …", options: ["28", "11", "8", "7"], answer: 1, solution: "1. Awalnya x=4 dan y=7, lalu temp menyimpan nilai x yaitu 4. 2. x diisi nilai y menjadi 7, kemudian y diisi nilai temp menjadi 4 (nilai x dan y bertukar). 3. Maka x + y = 7 + 4 = 11." },
    { q: "Perhatikan program berikut. FOR i ← 1 TO n DO FOR j ← 1 TO n DO PRINT '*'. ENDFOR ENDFOR. Kompleksitas waktu program tersebut adalah …", options: ["$O(n)$", "$O(1)$", "$O(2n)$", "$O(n^2)$"], answer: 3, solution: "1. Loop luar berjalan n kali dan untuk setiap putarannya loop dalam juga berjalan n kali. 2. Total operasi cetak adalah n × n = n². 3. Dalam notasi Big-O, kompleksitasnya adalah $O(n^2)$." },
    { q: "Perhatikan pseudocode berikut. data ← [3, 9, 2, 7]. maks ← data[0]. FOR tiap d dalam data DO IF d > maks THEN maks ← d. ENDFOR. PRINT maks. Nilai yang dicetak adalah …", options: ["21", "3", "9", "7"], answer: 2, solution: "1. Mulai dengan maks = 3 (elemen pertama). 2. Bandingkan satu per satu: 9 > 3 sehingga maks=9; 2 tidak lebih besar; 7 tidak lebih besar dari 9. 3. Nilai terbesar yang bertahan adalah 9." },
    { q: "Perhatikan pseudocode berikut. n ← 10. WHILE n > 0 DO PRINT n. n ← n - 3. ENDWHILE. Bilangan terakhir yang dicetak adalah …", options: ["4", "10", "0", "1"], answer: 3, solution: "1. Telusuri: n=10 dicetak lalu jadi 7; n=7 dicetak lalu jadi 4; n=4 dicetak lalu jadi 1. 2. n=1 dicetak lalu menjadi -2. 3. Karena -2 > 0 bernilai salah, loop berhenti; bilangan terakhir yang tercetak adalah 1." },
    { q: "Pada flowchart, simbol persegi panjang digunakan untuk menyatakan …", options: ["Input atau output data", "Awal atau akhir program", "Keputusan atau percabangan", "Proses atau perhitungan"], answer: 3, solution: "1. Simbol persegi panjang adalah simbol proses dalam flowchart standar. 2. Di dalamnya ditulis operasi seperti perhitungan atau penugasan nilai, misalnya total ← total + i. 3. Keputusan memakai belah ketupat, sedangkan input/output memakai jajar genjang." },
    { q: "Diketahui data = [5, 2, 8, 1]. Setelah SATU kali lintasan bubble sort (membandingkan pasangan bersebelahan dan menukar jika kiri lebih besar), susunan data menjadi …", options: ["[2, 1, 5, 8]", "[2, 5, 1, 8]", "[5, 2, 8, 1]", "[1, 2, 5, 8]"], answer: 1, solution: "1. Bandingkan 5 dan 2: 5 > 2 sehingga tukar menjadi [2, 5, 8, 1]. 2. Bandingkan 5 dan 8: tidak perlu tukar. 3. Bandingkan 8 dan 1: 8 > 1 sehingga tukar menjadi [2, 5, 1, 8]; satu lintasan selesai dan data belum tentu terurut penuh." },
    { q: "Data terurut [2, 4, 6, 8, 10, 12, 14] dicari angka 10 dengan binary search. Banyaknya perbandingan yang dilakukan sampai angka ditemukan adalah …", options: ["3 kali", "4 kali", "7 kali", "2 kali"], answer: 0, solution: "1. Perbandingan 1: tengah dari 7 data adalah indeks 3 bernilai 8; karena 10 > 8, cari di separuh kanan [10, 12, 14]. 2. Perbandingan 2: tengahnya bernilai 12; karena 10 < 12, cari di separuh kiri [10]. 3. Perbandingan 3: nilainya 10, cocok dan pencarian selesai." },
    { q: "Sebuah program menjumlahkan n buah bilangan dengan tepat satu buah loop yang memeriksa setiap bilangan sekali. Kompleksitas waktunya adalah …", options: ["$O(n^2)$", "$O(n)$", "$O(\\log n)$", "$O(1)$"], answer: 1, solution: "1. Jumlah operasi tumbuh sebanding dengan banyaknya data n karena tiap bilangan diproses tepat sekali. 2. Inilah definisi kompleksitas linear. 3. Maka kompleksitasnya adalah $O(n)$." },
    { q: "Perhatikan pseudocode berikut. f ← 1. FOR i ← 2 TO 4 DO f ← f * i. ENDFOR. PRINT f. Nilai yang dicetak adalah …", options: ["10", "9", "24", "12"], answer: 2, solution: "1. Telusuri: i=2 → f=2; i=3 → f=6; i=4 → f=24. 2. Ini menghitung 4! = 1 × 2 × 3 × 4. 3. Jadi nilai yang dicetak adalah 24." },
    { q: "Perhatikan pseudocode berikut. c ← 0. FOR i ← 1 TO 10 DO IF i MOD 2 = 1 THEN c ← c + 1. ENDFOR. PRINT c. Nilai yang dicetak adalah …", options: ["6", "5", "4", "10"], answer: 1, solution: "1. Kondisi i MOD 2 = 1 benar untuk bilangan ganjil. 2. Bilangan ganjil dari 1 sampai 10 adalah 1, 3, 5, 7, 9, totalnya 5 bilangan. 3. Setiap bilangan ganjil menambah c satu kali, sehingga c = 5." },
    { q: "Perhatikan pseudocode berikut. s ← 0. FOR i ← 1 TO 3 DO FOR j ← 1 TO 2 DO s ← s + 1. ENDFOR ENDFOR. PRINT s. Nilai yang dicetak adalah …", options: ["5", "3", "9", "6"], answer: 3, solution: "1. Loop luar berjalan 3 kali dan setiap putarannya loop dalam berjalan 2 kali. 2. Perintah s ← s + 1 dieksekusi sebanyak 3 × 2 = 6 kali. 3. Karena s mulai dari 0, nilai akhirnya adalah 6." },
    { q: "Perhatikan fungsi rekursif berikut. FUNCTION f(n): IF n = 0 THEN RETURN 1 ELSE RETURN n * f(n - 1). Nilai dari f(3) adalah …", options: ["9", "12", "3", "6"], answer: 3, solution: "1. Uraikan: f(3) = 3 × f(2); f(2) = 2 × f(1); f(1) = 1 × f(0); f(0) = 1 (kasus dasar). 2. Hitung mundur: f(1)=1, f(2)=2, f(3)=6. 3. Jadi f(3) = 6, yaitu 3 faktorial." },
    { q: "Perhatikan pseudocode berikut. FOR i ← 1 TO 6 DO IF i MOD 3 = 0 THEN PRINT i. ENDFOR. Bilangan yang dicetak adalah …", options: ["6 saja", "3 dan 6", "1 sampai 6", "1 dan 2"], answer: 1, solution: "1. Kondisi i MOD 3 = 0 benar untuk kelipatan 3. 2. Dari 1 sampai 6, kelipatan 3 adalah 3 dan 6. 3. Hanya kedua bilangan itu yang memenuhi syarat sehingga hanya keduanya yang dicetak." },
    { q: "Pada flowchart, simbol jajar genjang (parallelogram) digunakan untuk menyatakan …", options: ["Penghubung antar halaman", "Proses perhitungan", "Keputusan atau percabangan", "Input atau output data"], answer: 3, solution: "1. Jajar genjang adalah simbol standar untuk input (misalnya READ nama) dan output (misalnya PRINT hasil). 2. Bentuknya yang miring melambangkan data yang masuk atau keluar dari sistem. 3. Proses memakai persegi panjang, sedangkan keputusan memakai belah ketupat." },
    { q: "Untuk mencari sebuah nama dalam 200 data yang belum terurut dengan linear search, pada kasus terburuk banyaknya data yang diperiksa adalah …", options: ["1 data", "100 data", "400 data", "200 data"], answer: 3, solution: "1. Kasus terburuk artinya data yang dicari berada paling akhir atau tidak ada sama sekali. 2. Linear search memeriksa satu per satu dari awal sampai akhir. 3. Maka seluruh 200 data harus diperiksa." },
    { q: "Perhatikan pseudocode berikut. a ← 10. b ← 20. a ← a + b. b ← a - b. a ← a - b. PRINT a, b. Hasil yang dicetak adalah …", options: ["10, 20", "20, 10", "30, 20", "30, 10"], answer: 1, solution: "1. Setelah a ← a + b, nilai a menjadi 30 sedangkan b tetap 20. 2. Setelah b ← a - b, nilai b menjadi 30 - 20 = 10. 3. Setelah a ← a - b, nilai a menjadi 30 - 10 = 20; jadi tercetak 20, 10 (nilai a dan b bertukar tanpa variabel bantu)." },
    { q: "Perhatikan pseudocode berikut. jumlah ← 0. FOR i ← 1 TO 4 DO READ x. jumlah ← jumlah + x. ENDFOR. PRINT jumlah / 4. Jika masukan berturut-turut adalah 8, 6, 10, 4, nilai yang dicetak adalah …", options: ["7", "6", "8", "28"], answer: 0, solution: "1. Jumlahkan semua masukan: 8 + 6 + 10 + 4 = 28. 2. Program membagi jumlah tersebut dengan 4 untuk mencari rata-rata. 3. Maka 28 / 4 = 7." },
    { q: "Algoritma A memeriksa setiap data tepat sekali, sedangkan algoritma B memeriksa setiap pasangan data. Untuk data berjumlah sangat besar, pernyataan yang tepat adalah …", options: ["Algoritma A lebih efisien daripada algoritma B", "Kecepatan hanya ditentukan bahasa pemrograman", "Keduanya selalu sama cepat", "Algoritma B lebih efisien daripada algoritma A"], answer: 0, solution: "1. Algoritma A berkompleksitas $O(n)$ sedangkan algoritma B berkompleksitas $O(n^2)$. 2. Pertumbuhan kuadrat jauh lebih cepat daripada pertumbuhan linear saat n besar. 3. Jadi algoritma A lebih efisien untuk data yang sangat besar." },
    { q: "Perhatikan pseudocode berikut. k ← 1. WHILE k < 50 DO k ← k * 3. ENDWHILE. PRINT k. Nilai yang dicetak adalah …", options: ["27", "81", "54", "50"], answer: 1, solution: "1. Telusuri: k=1 (< 50) menjadi 3; k=3 menjadi 9; k=9 menjadi 27; k=27 menjadi 81. 2. Sekarang 81 < 50 bernilai salah sehingga loop berhenti. 3. Nilai terakhir k adalah 81." },
    { q: "Perhatikan pseudocode berikut. p ← 2. FOR i ← 1 TO 3 DO p ← p * p. ENDFOR. PRINT p. Nilai yang dicetak adalah …", options: ["16", "8", "64", "256"], answer: 3, solution: "1. Telusuri: putaran 1 → p = 2 × 2 = 4; putaran 2 → p = 4 × 4 = 16. 2. Putaran 3 → p = 16 × 16 = 256. 3. Jadi nilai yang dicetak adalah 256." },
    { q: "Dalam menyelesaikan masalah dengan komputer, langkah pertama yang paling tepat adalah …", options: ["Langsung menulis kode program", "Menebak-nebak solusinya", "Menggambar tampilan program", "Memahami dan menganalisis masalah dengan cermat"], answer: 3, solution: "1. Algoritma yang baik lahir dari pemahaman masalah yang benar: apa masukannya, apa keluarannya, dan apa batasannya. 2. Langsung menulis kode tanpa analisis berisiko menghasilkan program yang salah sasaran. 3. Karena itu analisis masalah selalu menjadi langkah pertama." },
    { q: "Perhatikan pseudocode berikut. n ← 15. IF n MOD 5 = 0 THEN IF n MOD 3 = 0 THEN PRINT 'A' ELSE PRINT 'B'. ELSE PRINT 'C'. Huruf yang dicetak adalah …", options: ["A", "C", "B", "Tidak ada yang dicetak"], answer: 0, solution: "1. Cek kondisi luar: 15 MOD 5 = 0 bernilai benar, masuk ke cabang dalam. 2. Cek kondisi dalam: 15 MOD 3 = 0 juga bernilai benar. 3. Maka perintah yang dijalankan adalah PRINT 'A'." },
    { q: "Mengambil sebuah elemen array langsung berdasarkan nomor indeksnya memiliki kompleksitas waktu …", options: ["$O(n \\log n)$", "$O(n)$", "$O(1)$", "$O(n^2)$"], answer: 2, solution: "1. Alamat memori elemen array dapat dihitung langsung dari alamat awal ditambah indeks kali ukuran elemen. 2. Waktu yang dibutuhkan tetap sama berapa pun ukuran array. 3. Kompleksitas waktu konstan dilambangkan $O(1)$." },
    { q: "Ke dalam sebuah stack dilakukan push 1, push 2, pop, push 3, pop, pop. Urutan nilai yang keluar dari stack adalah …", options: ["3, 2, 1", "1, 2, 3", "2, 3, 1", "1, 3, 2"], answer: 2, solution: "1. Setelah push 1 dan push 2, tumpukan berisi [1, 2] dengan 2 di atas. 2. Pop pertama mengeluarkan 2; push 3 membuat tumpukan [1, 3]. 3. Pop kedua mengeluarkan 3, pop ketiga mengeluarkan 1; urutannya 2, 3, 1." },
    { q: "Ke dalam sebuah queue dilakukan enqueue 10, enqueue 20, dequeue, enqueue 30, dequeue. Urutan nilai yang keluar dari queue adalah …", options: ["10 lalu 30", "30 lalu 20", "20 lalu 10", "10 lalu 20"], answer: 3, solution: "1. Setelah enqueue 10 dan 20, antrean berisi [10, 20] dengan 10 paling depan. 2. Dequeue pertama mengeluarkan 10; enqueue 30 membuat antrean [20, 30]. 3. Dequeue kedua mengeluarkan 20; urutannya 10 lalu 20." },
    { q: "Sebuah stack berisi [4, 9, 2] dengan 2 berada paling atas. Setelah operasi peek (melihat elemen teratas), ukuran stack menjadi …", options: ["4", "0", "2", "3"], answer: 3, solution: "1. Operasi peek hanya melihat elemen teratas tanpa menghapusnya. 2. Karena tidak ada elemen yang dihapus atau ditambah, isi stack tetap [4, 9, 2]. 3. Maka ukurannya tetap 3." },
    { q: "Melakukan pop pada stack yang sedang kosong akan menyebabkan kondisi yang disebut …", options: ["Normal", "Stack underflow", "Stack overflow", "Stack penuh"], answer: 1, solution: "1. Pop berarti mengambil elemen dari tumpukan. 2. Jika tumpukan kosong, tidak ada yang bisa diambil sehingga terjadi kesalahan underflow (kekurangan). 3. Overflow adalah kebalikannya, yaitu push ke tumpukan yang sudah penuh." },
    { q: "Melakukan push pada stack yang kapasitasnya sudah penuh akan menyebabkan kondisi yang disebut …", options: ["Stack overflow", "Stack underflow", "Stack kosong", "Normal"], answer: 0, solution: "1. Push berarti menambah elemen ke tumpukan. 2. Jika kapasitas sudah penuh, tidak ada ruang tersisa sehingga terjadi kesalahan overflow (kelebihan). 3. Underflow adalah kebalikannya, yaitu pop dari tumpukan yang kosong." },
    { q: "Pada sebuah queue, ujung tempat elemen keluar (elemen yang paling dulu masuk) disebut …", options: ["Front", "Top", "Head pointer", "Rear"], answer: 0, solution: "1. Queue memiliki dua ujung: belakang untuk masuk dan depan untuk keluar. 2. Ujung depan tempat dequeue dilakukan disebut front. 3. Rear adalah ujung belakang tempat enqueue, sedangkan top adalah istilah untuk stack." },
    { q: "Sebuah linked list memiliki 3 node A → B → C dengan A sebagai head. Setelah node D disisipkan di paling depan, head yang baru adalah …", options: ["C", "D", "A", "B"], answer: 1, solution: "1. Head selalu menunjuk ke node pertama dalam rantai. 2. Setelah D disisipkan di depan A, rantai menjadi D → A → B → C. 3. Node pertama sekarang adalah D, sehingga head menunjuk ke D." },
    { q: "Untuk menghitung banyaknya node dalam sebuah linked list, cara yang dilakukan adalah …", options: ["Mengakses langsung dengan indeks", "Membagi ukuran memori total", "Menelusuri dari head sambil menghitung satu per satu sampai pointer NULL", "Menghitung dari tail ke head"], answer: 2, solution: "1. Linked list tidak menyimpan jumlah nodenya secara otomatis dan tidak mendukung akses indeks. 2. Satu-satunya cara adalah traversal: mulai dari head, hitung setiap node yang dikunjungi. 3. Penelusuran berhenti saat pointer menunjuk NULL (ujung rantai)." },
    { q: "Diketahui array data = [10, 20, 30, 40]. Nomor indeks dari elemen terakhir adalah …", options: ["3", "40", "0", "4"], answer: 0, solution: "1. Indeks array dimulai dari 0, bukan dari 1. 2. Elemen-elemennya: indeks 0 = 10, indeks 1 = 20, indeks 2 = 30, indeks 3 = 40. 3. Elemen terakhir (40) berada pada indeks 3." },
    { q: "Sebuah array dua dimensi berukuran 3 baris × 4 kolom dapat menampung elemen sebanyak …", options: ["16", "7", "12", "3"], answer: 2, solution: "1. Array dua dimensi adalah susunan baris dan kolom seperti tabel. 2. Total sel = jumlah baris × jumlah kolom = 3 × 4. 3. Hasilnya adalah 12 elemen." },
    { q: "Fitur undo (batalkan pengetikan terakhir) pada aplikasi pengolah kata paling tepat dimodelkan dengan …", options: ["Linked list melingkar", "Queue", "Stack", "Array dua dimensi"], answer: 2, solution: "1. Undo membatalkan aksi yang paling terakhir dilakukan terlebih dahulu. 2. Ini adalah perilaku LIFO: aksi terakhir masuk adalah yang pertama dibatalkan. 3. Setiap pengetikan di-push, dan undo melakukan pop." },
    { q: "Urutan keluarnya data pada struktur data queue bersifat …", options: ["Acak tanpa aturan", "Yang masuk belakangan keluar duluan (LIFO)", "Yang masuk duluan keluar duluan (FIFO)", "Berdasarkan abjad"], answer: 2, solution: "1. Queue meniru antrean: siapa datang duluan dilayani duluan. 2. Sifat ini disebut FIFO (First In First Out). 3. LIFO adalah sifat stack, bukan queue." },
    { q: "Untuk program yang sering menyisipkan dan menghapus data di tengah-tengah kumpulan data, struktur yang lebih efisien daripada array adalah …", options: ["Stack", "Linked list", "Variabel tunggal", "Konstanta"], answer: 1, solution: "1. Menyisip di tengah array mengharuskan menggeser semua elemen sesudahnya, yang mahal. 2. Pada linked list, penyisipan cukup dengan mengubah dua buah pointer tanpa menggeser elemen lain. 3. Karena itu linked list lebih efisien untuk operasi sisip/hapus di tengah." },
    { q: "Ke dalam sebuah stack dilakukan push 'a', push 'b', push 'c', pop, push 'd'. Elemen yang berada paling atas sekarang adalah …", options: ["'c'", "'b'", "'d'", "'a'"], answer: 2, solution: "1. Setelah push a, b, c, tumpukan berisi [a, b, c] dengan c di atas. 2. Operasi pop menghapus c sehingga tumpukan menjadi [a, b]. 3. Push 'd' menaruh d paling atas, sehingga elemen teratas adalah 'd'." },
    { q: "Ke dalam sebuah queue dilakukan enqueue P, enqueue Q, enqueue R, dequeue, dequeue, enqueue S. Elemen yang berada paling depan sekarang adalah …", options: ["P", "S", "R", "Q"], answer: 2, solution: "1. Setelah enqueue P, Q, R, antrean berisi [P, Q, R] dengan P paling depan. 2. Dua kali dequeue mengeluarkan P lalu Q, tersisa [R]. 3. Enqueue S membuat antrean [R, S]; yang paling depan adalah R." },
    { q: "Operasi pada stack yang berfungsi melihat elemen teratas TANPA menghapusnya disebut …", options: ["Peek (top)", "Push", "Clear", "Pop"], answer: 0, solution: "1. Pop mengambil sekaligus menghapus elemen teratas. 2. Peek (atau top) hanya membaca nilainya sehingga isi stack tidak berubah. 3. Push menambah elemen, sedangkan clear mengosongkan seluruh stack." },
    { q: "Operasi dequeue pada queue akan …", options: ["Menambah elemen di belakang", "Menghapus dan mengembalikan elemen paling depan", "Menghapus seluruh isi antrean", "Menukar depan dan belakang"], answer: 1, solution: "1. Dequeue adalah operasi keluar pada antrean. 2. Ia menghapus elemen di ujung front sekaligus mengembalikan nilainya. 3. Operasi menambah elemen di belakang disebut enqueue." },
    { q: "Pada linked list, node terakhir (tail) dapat dikenali karena …", options: ["Datanya selalu nol", "Tidak memiliki data", "Menunjuk kembali ke head", "Pointernya menunjuk ke NULL"], answer: 3, solution: "1. Setiap node menyimpan data dan pointer ke node berikutnya. 2. Node terakhir tidak memiliki penerus, sehingga pointernya diisi NULL sebagai penanda akhir rantai. 3. Menunjuk kembali ke head hanya terjadi pada linked list melingkar." },
    { q: "Struktur data yang elemennya hanya bisa ditambah dan diambil dari SATU ujung yang sama adalah …", options: ["Linked list", "Stack", "Queue", "Array"], answer: 1, solution: "1. Pada stack, push dan pop keduanya dilakukan di ujung yang sama yaitu top. 2. Queue memakai dua ujung berbeda (masuk di belakang, keluar di depan). 3. Array dan linked list bisa diakses dari berbagai posisi, bukan satu ujung saja." },
    { q: "Antrean melingkar (circular queue) dibuat dengan tujuan …", options: ["Memanfaatkan kembali ruang kosong di depan antrean agar memori array tidak terbuang", "Mengurutkan isi antrean", "Mengubah queue menjadi stack", "Membuat antrean menjadi tidak terbatas"], answer: 0, solution: "1. Pada queue berbasis array biasa, ruang di depan yang sudah di-dequeue tidak bisa dipakai lagi. 2. Circular queue membuat ujung belakang tersambung ke depan sehingga ruang kosong itu dipakai ulang. 3. Hasilnya memori array termanfaatkan penuh tanpa menggeser elemen." },
    { q: "Contoh penerapan stack di dalam sistem operasi dan bahasa pemrograman adalah …", options: ["Tumpukan pemanggilan fungsi (call stack)", "Antrean pencetakan", "Riwayat unduhan", "Daftar kontak telepon"], answer: 0, solution: "1. Saat fungsi memanggil fungsi lain, komputer menyimpan alamat kembali dalam call stack. 2. Fungsi yang terakhir dipanggil selesai paling dulu, persis perilaku LIFO. 3. Antrean pencetakan dan riwayat unduhan bersifat FIFO sehingga memakai queue." },
    { q: "Ke dalam sebuah stack dilakukan push 5, push 9, pop, push 7, pop, pop. Urutan nilai yang keluar adalah …", options: ["9, 5, 7", "7, 9, 5", "5, 9, 7", "9, 7, 5"], answer: 3, solution: "1. Setelah push 5 dan push 9, tumpukan [5, 9]; pop pertama mengeluarkan 9. 2. Push 7 membuat tumpukan [5, 7]; pop kedua mengeluarkan 7. 3. Pop ketiga mengeluarkan 5; urutan keluarnya 9, 7, 5." },
    { q: "Menghapus sebuah node di tengah linked list pada dasarnya hanya memerlukan …", options: ["Mengubah pointer node sebelumnya agar melewati node yang dihapus", "Mengurutkan ulang semua data", "Menghapus seluruh list lalu membuat ulang", "Menggeser semua node sesudahnya"], answer: 0, solution: "1. Node-node linked list tidak harus bersebelahan di memori, hanya terhubung lewat pointer. 2. Untuk menghapus node tengah, cukup arahkan pointer node sebelumnya langsung ke node sesudahnya. 3. Tidak ada penggeseran elemen seperti pada array." },
    { q: "Pernyataan yang TEPAT tentang perbedaan array dan linked list adalah …", options: ["Array mendukung akses indeks langsung, linked list harus ditelusuri dari head", "Array ukurannya selalu bisa membesar otomatis", "Linked list tidak bisa menyimpan data teks", "Linked list memakai memori yang bersebelahan seperti array"], answer: 0, solution: "1. Elemen array tersimpan berurutan sehingga data[i] dihitung langsung, sedangkan node linked list tersebar dan hanya terhubung lewat pointer. 2. Untuk mencapai node ke-i harus menelusuri satu per satu dari head. 3. Ukuran array statis umumnya tetap, dan linked list bisa menyimpan data apa pun." },
    { q: "Untuk menampilkan nama siswa diurutkan dari nilai TERTINGGI ke terendah, perintah SQL yang tepat adalah …", options: ["SELECT nama FROM siswa ORDER BY nilai DESC;", "SELECT nama FROM siswa SORT BY nilai;", "SELECT nama FROM siswa WHERE nilai DESC;", "SELECT nama FROM siswa ORDER BY nilai;"], answer: 0, solution: "1. Pengurutan hasil query memakai klausa ORDER BY. 2. Secara default urutannya menaik (ASC), sehingga untuk tertinggi ke terendah perlu tambahan DESC. 3. WHERE dipakai untuk menyaring bukan mengurut, dan SORT BY bukan sintaks SQL standar." },
    { q: "Perintah UPDATE siswa SET kelas = 'X-2' WHERE nama = 'Budi'; akan berakibat …", options: ["Mengubah kelas Budi menjadi X-2", "Menghapus seluruh data siswa", "Mengubah nama semua siswa menjadi Budi", "Menambah siswa baru bernama Budi"], answer: 0, solution: "1. Perintah UPDATE berfungsi mengubah data yang sudah ada, bukan menambah atau menghapus. 2. Klausa SET menentukan kolom dan nilai baru, yaitu kelas menjadi X-2. 3. Klausa WHERE membatasi perubahan hanya pada baris bernama Budi." },
    { q: "Perintah DELETE FROM nilai WHERE id = 3; akan berakibat …", options: ["Menghapus tabel nilai", "Menghapus seluruh baris tabel nilai", "Menghapus baris data dengan id 3", "Menghapus kolom id"], answer: 2, solution: "1. Perintah DELETE menghapus baris (record), bukan tabel atau kolom. 2. Klausa WHERE id = 3 membatasi hanya baris dengan id 3 yang dihapus. 3. Tabel dan baris lainnya tetap utuh." },
    { q: "SELECT * FROM siswa WHERE nilai > 80 AND kelas = 'X-1'; Perintah tersebut menampilkan …", options: ["Siswa kelas X-1 atau yang nilainya di atas 80", "Semua siswa kelas X-1", "Siswa kelas X-1 yang nilainya di atas 80", "Siswa bernilai di atas 80 dari semua kelas"], answer: 2, solution: "1. Operator AND berarti kedua syarat harus terpenuhi sekaligus. 2. Syarat pertama: nilai > 80; syarat kedua: kelas = 'X-1'. 3. Jadi yang tampil hanya siswa kelas X-1 dengan nilai di atas 80." },
    { q: "Dua orang siswa tidak sengaja dimasukkan dengan NIS yang sama. Aturan basis data yang dilanggar adalah …", options: ["Jumlah kolom", "Urutan abjad", "Keunikan primary key", "Foreign key"], answer: 2, solution: "1. NIS berperan sebagai primary key yang menjadi identitas unik tiap siswa. 2. Syarat primary key adalah nilainya tidak boleh sama antar baris. 3. Memasukkan NIS ganda melanggar keunikan tersebut sehingga ditolak sistem." },
    { q: "Dalam basis data sekolah, hubungan antara tabel siswa dan tabel nilai adalah …", options: ["Satu siswa dapat memiliki banyak nilai (one-to-many)", "Satu siswa hanya boleh punya satu nilai", "Satu nilai hanya untuk satu sekolah", "Tidak ada hubungan sama sekali"], answer: 0, solution: "1. Setiap siswa mengikuti banyak ulangan sehingga memiliki banyak baris nilai. 2. Sebaliknya, tiap baris nilai hanya milik satu siswa. 3. Pola satu ke banyak ini disebut relasi one-to-many." },
    { q: "Jika perintah ORDER BY ditulis tanpa ASC atau DESC, urutan hasil yang dipakai secara default adalah …", options: ["Sesuai urutan dimasukkan", "Menaik / kecil ke besar (ASC)", "Menurun / besar ke kecil (DESC)", "Acak"], answer: 1, solution: "1. Standar SQL menetapkan urutan default ORDER BY adalah menaik. 2. Contoh: ORDER BY nama menampilkan A ke Z tanpa perlu menulis ASC. 3. Untuk urutan menurun harus ditulis DESC secara eksplisit." },
    { q: "Perintah INSERT INTO siswa (nama) VALUES ('Ani'); dijalankan pada tabel siswa berkolom id, nama, kelas. Kolom id dan kelas akan berisi …", options: ["Error karena tidak lengkap", "Teks kosong yang merusak tabel", "Data milik siswa lain", "Nilai otomatis atau NULL sesuai aturan kolom"], answer: 3, solution: "1. SQL memperbolehkan mengisi sebagian kolom saja. 2. Kolom yang tidak disebut akan diisi nilai default, auto-increment, atau NULL bila diperbolehkan. 3. Perintah tidak error selama kolom wajib (NOT NULL tanpa default) sudah terpenuhi." },
    { q: "Kumpulan tabel-tabel yang saling berhubungan dan tersimpan secara terorganisasi disebut …", options: ["Folder", "File teks", "Basis data (database)", "Spreadsheet lepas"], answer: 2, solution: "1. Basis data adalah wadah terstruktur untuk menyimpan banyak tabel beserta relasinya. 2. Ia dikelola oleh DBMS seperti MySQL atau SQLite. 3. File teks atau folder biasa tidak memiliki struktur relasi antar tabel." },
    { q: "Pada tabel siswa, nama, kelas, dan nilai disebut …", options: ["Tabel", "Field / atribut / kolom", "Record", "Primary key"], answer: 1, solution: "1. Arah vertikal pada tabel (nama, kelas, nilai) adalah kolom yang disebut field atau atribut. 2. Record adalah arah horizontal yaitu satu baris data utuh. 3. Primary key hanyalah salah satu kolom yang menjadi identitas unik." },
    { q: "Perintah UPDATE nilai SET nilai = 0; yang ditulis TANPA klausa WHERE akan berakibat …", options: ["Tidak ada perubahan", "Tabel nilai terhapus", "Seluruh baris kolom nilai menjadi 0", "Hanya baris pertama yang berubah"], answer: 2, solution: "1. Tanpa WHERE, perintah UPDATE berlaku untuk semua baris dalam tabel. 2. Semua nilai pada kolom nilai akan tertimpa menjadi 0. 3. Ini sama berbahayanya dengan DELETE tanpa WHERE, sehingga filter selalu wajib diperiksa." },
    { q: "SELECT nama FROM siswa WHERE kelas = 'X-2' OR kelas = 'X-3'; Perintah tersebut menampilkan …", options: ["Siswa selain kelas X-2 dan X-3", "Siswa kelas X-2 dan siswa kelas X-3", "Semua siswa tanpa kecuali", "Hanya siswa kelas X-2"], answer: 1, solution: "1. Operator OR berarti cukup salah satu syarat terpenuhi. 2. Baris dengan kelas X-2 lolos syarat pertama, baris kelas X-3 lolos syarat kedua. 3. Gabungan keduanya yang ditampilkan." },
    { q: "Tipe data yang paling tepat untuk menyimpan nama siswa seperti 'Budi Santoso' adalah …", options: ["VARCHAR / TEXT", "BOOLEAN", "DATE", "INTEGER"], answer: 0, solution: "1. Nama adalah rangkaian karakter (string) dengan panjang bervariasi. 2. Tipe VARCHAR/TEXT dirancang untuk menyimpan teks. 3. INTEGER untuk bilangan bulat, DATE untuk tanggal, dan BOOLEAN untuk benar/salah." },
    { q: "Tipe data yang paling tepat untuk menyimpan tanggal lahir siswa adalah …", options: ["BOOLEAN", "INTEGER", "VARCHAR", "DATE"], answer: 3, solution: "1. Tanggal lahir adalah data kalender seperti 2010-05-21. 2. Tipe DATE menyimpan tanggal dalam format baku dan mendukung perhitungan selisih tanggal. 3. Menyimpannya sebagai teks membuat validasi dan perhitungan tanggal menjadi sulit." },
    { q: "Di perpustakaan, tabel peminjaman memiliki kolom id_anggota yang merujuk ke tabel anggota. Kolom id_anggota tersebut berperan sebagai …", options: ["Foreign key yang menghubungkan ke tabel anggota", "Kolom tanpa fungsi", "Primary key tabel peminjaman", "Nama tabel baru"], answer: 0, solution: "1. Kolom yang nilainya merujuk ke primary key tabel lain disebut foreign key. 2. Ia memastikan setiap peminjaman terhubung ke anggota yang benar-benar terdaftar. 3. Primary key tabel peminjaman adalah identitas unik baris peminjaman itu sendiri, bukan id_anggota." },
    { q: "Rancangan struktur tabel (nama tabel, kolom, tipe data, dan kunci) disebut …", options: ["Skema", "Backup", "Query", "Record"], answer: 0, solution: "1. Skema adalah cetak biru basis data sebelum diisi data. 2. Ia mendefinisikan tabel apa saja yang ada beserta kolom dan relasinya. 3. Record adalah isi baris, query adalah perintah, dan backup adalah salinan cadangan." },
    { q: "SELECT nama FROM siswa WHERE kelas = 'X-3' ORDER BY nama; Perintah tersebut menampilkan …", options: ["Semua nama siswa tanpa urutan", "Jumlah siswa kelas X-3", "Nama siswa kelas X-3 diurutkan sesuai abjad", "Nama siswa kelas X-3 diurutkan dari Z ke A"], answer: 2, solution: "1. WHERE menyaring hanya baris kelas X-3. 2. ORDER BY nama tanpa DESC berarti urutan menaik sesuai abjad (A ke Z). 3. Kolom yang ditampilkan hanya nama sesuai SELECT." },
    { q: "Perbedaan perintah DELETE FROM siswa; dan DROP TABLE siswa; adalah …", options: ["DROP hanya menghapus satu baris", "DELETE menghapus struktur tabel", "Keduanya sama saja", "DELETE menghapus isi baris, DROP menghapus tabel beserta strukturnya"], answer: 3, solution: "1. DELETE bekerja pada data: baris-baris dihapus tetapi tabel dan kolomnya tetap ada. 2. DROP bekerja pada struktur: tabel dihapus total dari basis data. 3. Setelah DROP, tabel harus dibuat ulang dengan CREATE TABLE bila dibutuhkan lagi." },
    { q: "Hubungan antara siswa dan ekstrakurikuler (satu siswa bisa ikut banyak ekskul, satu ekskul diikuti banyak siswa) disebut relasi …", options: ["One-to-many", "Many-to-many", "One-to-one", "Tanpa relasi"], answer: 1, solution: "1. Kedua arah hubungannya banyak: siswa→banyak ekskul dan ekskul→banyak siswa. 2. Pola ini disebut many-to-many. 3. Dalam praktik ia dipecah menjadi dua relasi one-to-many lewat tabel perantara." },
    { q: "Sebuah kolom nilai ujian ada yang belum diisi sehingga sistem menyimpannya sebagai NULL. Arti NULL di sini adalah …", options: ["Terjadi error", "Data kosong / belum diketahui", "Nilainya negatif", "Nilainya nol"], answer: 1, solution: "1. NULL berarti tidak ada nilai, bukan nol atau string kosong. 2. Ia menandakan data belum diisi atau belum diketahui. 3. Karena itu NULL tidak sama dengan 0 dalam perhitungan basis data." },
    { q: "Untuk menampilkan SELURUH kolom dari tabel buku, perintah yang tepat adalah …", options: ["SELECT ALL FROM buku;", "SHOW * buku;", "SELECT * FROM buku;", "SELECT kolom FROM buku;"], answer: 2, solution: "1. Tanda bintang (*) adalah singkatan untuk semua kolom dalam tabel. 2. Sintaks lengkapnya SELECT * FROM nama_tabel. 3. Pilihan lain bukan sintaks SQL yang valid." },
    { q: "Perintah INSERT INTO nilai VALUES (5, 90); ditulis tanpa menyebut nama kolom. Syarat agar perintah ini benar adalah …", options: ["Kolom harus bertipe teks semua", "Nilai 5 dan 90 harus sesuai urutan dan jumlah kolom tabel", "Harus memakai WHERE", "Tabel harus kosong"], answer: 1, solution: "1. Tanpa daftar kolom, SQL menganggap nilai diberikan untuk semua kolom berurutan. 2. Jumlah nilai harus sama dengan jumlah kolom dan tipenya cocok. 3. Cara yang lebih aman adalah menyebut nama kolom secara eksplisit." },
    { q: "Agar setiap data nilai selalu merujuk ke siswa yang benar-benar ada di tabel siswa, aturan yang dipakai adalah …", options: ["Backup harian", "Password tabel", "Integritas referensial lewat foreign key", "Urutan abjad nama"], answer: 2, solution: "1. Foreign key membatasi nilai kolom agar hanya boleh merujuk ke primary key yang ada. 2. Aturan ini disebut integritas referensial: tidak boleh ada nilai yatim tanpa induk. 3. Jika siswa dihapus, sistem akan menolak atau menyesuaikan nilai terkait." },
    { q: "Perintah SQL yang digunakan untuk MEMBUAT tabel baru bernama guru adalah …", options: ["NEW TABLE guru;", "BUILD guru;", "CREATE TABLE guru (...);", "MAKE TABLE guru;"], answer: 2, solution: "1. Perintah DDL untuk membuat objek basis data adalah CREATE. 2. Sintaksnya CREATE TABLE nama_tabel diikuti definisi kolom dalam kurung. 3. MAKE, NEW, dan BUILD bukan perintah SQL standar." },
    { q: "Alamat IP 192.168.10.5 termasuk jenis alamat IP …", options: ["Alamat MAC", "Alamat broadcast", "Privat untuk jaringan lokal", "Publik yang bisa diakses internet langsung"], answer: 2, solution: "1. Rentang 192.168.x.x dicadangkan khusus untuk jaringan privat/lokal. 2. Alamat privat tidak bisa diakses langsung dari internet tanpa NAT. 3. Alamat broadcast diakhiri .255, sedangkan alamat MAC adalah alamat fisik perangkat." },
    { q: "Sebuah komputer beralamat 192.168.5.77 dengan subnet mask /24. Alamat network-nya adalah …", options: ["192.168.0.0", "192.168.5.0", "192.168.5.1", "192.168.5.77"], answer: 1, solution: "1. Pada /24, tiga oktet pertama adalah bagian network dan oktet terakhir bagian host. 2. Untuk mendapat alamat network, bagian host diisi nol. 3. Maka 192.168.5.77 menjadi 192.168.5.0." },
    { q: "Pada jaringan 192.168.5.0/24, alamat yang dipakai untuk mengirim data ke SEMUA host sekaligus adalah …", options: ["192.168.5.0", "192.168.5.100", "192.168.5.255", "192.168.5.1"], answer: 2, solution: "1. Alamat broadcast memakai semua bit host bernilai 1, yaitu oktet terakhir 255. 2. Paket ke alamat ini diterima oleh seluruh host dalam jaringan. 3. Alamat .0 adalah network ID dan tidak bisa dipakai host." },
    { q: "Saat pertama kali mengetik alamat situs di browser, hal pertama yang dilakukan komputer agar bisa terhubung adalah …", options: ["Mengunduh seluruh isi situs", "Mematikan firewall", "Meminta server DNS menerjemahkan nama domain menjadi alamat IP", "Mengganti alamat IP sendiri"], answer: 2, solution: "1. Komputer hanya bisa terhubung memakai alamat IP numerik. 2. Sebelum koneksi dibuat, nama domain harus diterjemahkan lewat query DNS. 3. Setelah IP didapat, barulah browser mengirim permintaan HTTP ke server." },
    { q: "Layanan yang memberikan alamat IP secara otomatis kepada perangkat yang baru terhubung ke jaringan disebut …", options: ["FTP", "DHCP", "DNS", "HTTP"], answer: 1, solution: "1. DHCP (Dynamic Host Configuration Protocol) membagikan konfigurasi IP otomatis. 2. Perangkat tidak perlu diatur manual satu per satu. 3. DNS menerjemahkan nama domain, sedangkan FTP dan HTTP adalah protokol transfer data." },
    { q: "Pada topologi bus, semua komputer terhubung ke satu kabel utama. Kelemahan utamanya adalah …", options: ["Tidak bisa memakai internet", "Jika kabel utama putus, seluruh jaringan mati", "Biaya sangat mahal", "Hanya untuk dua komputer"], answer: 1, solution: "1. Kabel backbone adalah satu-satunya jalur komunikasi semua node. 2. Putusnya satu titik pada kabel utama memutus seluruh jaringan. 3. Kelebihannya justru murah dan mudah dipasang untuk jaringan kecil." },
    { q: "Ciri khas topologi ring adalah …", options: ["Tidak memakai kabel sama sekali", "Semua node terhubung ke switch pusat", "Data bergerak memutar dari satu node ke node berikutnya", "Setiap node punya kabel ke semua node lain"], answer: 2, solution: "1. Pada topologi ring, node-node dirangkai melingkar seperti cincin. 2. Data berjalan satu arah melewati setiap node sampai tiba di tujuan. 3. Switch pusat adalah ciri topologi star, sedangkan semua-terhubung-ke-semua adalah mesh." },
    { q: "Topologi mesh dipilih untuk jaringan yang menuntut keandalan sangat tinggi karena …", options: ["Tidak butuh perangkat apa pun", "Tersedia banyak jalur alternatif jika satu jalur putus", "Kecepatannya selalu lambat", "Biayanya paling murah"], answer: 1, solution: "1. Pada mesh, tiap node terhubung ke banyak node lain sehingga jalurnya berlapis. 2. Jika satu kabel putus, data otomatis lewat jalur lain. 3. Kelemahannya adalah biaya kabel dan konfigurasi yang sangat mahal." },
    { q: "Perbedaan utama HTTPS dan HTTP adalah …", options: ["HTTP hanya untuk gambar", "HTTPS tidak butuh internet", "HTTPS lebih lambat membuka teks", "HTTPS mengenkripsi data dengan TLS sehingga aman dari penyadapan"], answer: 3, solution: "1. Huruf S pada HTTPS berarti Secure. 2. Seluruh komunikasi dienkripsi memakai TLS/SSL sehingga tidak bisa dibaca penyadap. 3. HTTP mengirim data sebagai teks biasa yang mudah disadap." },
    { q: "Nomor port yang umum dipakai oleh protokol HTTP dan HTTPS berturut-turut adalah …", options: ["21 dan 22", "25 dan 110", "53 dan 67", "80 dan 443"], answer: 3, solution: "1. Setiap layanan jaringan punya nomor port baku agar paket sampai ke aplikasi yang tepat. 2. HTTP memakai port 80, sedangkan HTTPS memakai port 443. 3. Port 21/22 untuk FTP/SSH dan 25 untuk SMTP." },
    { q: "Agar file yang dikirim lewat TCP bisa disusun kembali dengan benar di tujuan meskipun paket datang tidak berurutan, setiap paket diberi …", options: ["Ukuran font", "Warna label", "Nama pengirim saja", "Nomor urut (sequence number)"], answer: 3, solution: "1. Paket-paket TCP bisa menempuh rute berbeda sehingga tiba tidak berurutan. 2. Nomor urut memungkinkan penerima menyusun ulang paket sesuai urutan aslinya. 3. Paket yang hilang juga terdeteksi dari nomor urut yang melompat." },
    { q: "Perbedaan alamat IP dan alamat MAC yang tepat adalah …", options: ["Alamat IP hanya untuk kabel", "Keduanya selalu sama", "Alamat MAC bisa diubah bebas setiap detik", "Alamat IP bersifat logis dan bisa berubah, alamat MAC bersifat fisik dan tetap dari pabrik"], answer: 3, solution: "1. Alamat IP diberikan oleh jaringan dan bisa berganti (misalnya lewat DHCP). 2. Alamat MAC ditanam pabrik pada kartu jaringan dan bersifat permanen. 3. Keduanya bekerja di layer berbeda: IP di layer network, MAC di layer data link." },
    { q: "Perintah ping ke sebuah alamat IP pada dasarnya digunakan untuk …", options: ["Menguji apakah perangkat tujuan terjangkau dan mengukur waktu respons", "Mengunduh file besar", "Mengganti alamat IP", "Mempercepat koneksi"], answer: 0, solution: "1. Ping mengirim paket kecil ICMP dan menunggu balasannya. 2. Balasan yang kembali berarti jalur ke tujuan berfungsi, sekaligus terlihat latensinya. 3. Jika tidak ada balasan, kemungkinan perangkat mati atau jaringan terputus." },
    { q: "Dalam jaringan lokal, perangkat yang menjadi pintu keluar menuju jaringan lain atau internet disebut …", options: ["Hub", "Repeater", "Gateway", "Switch"], answer: 2, solution: "1. Gateway adalah titik perantara antar jaringan yang berbeda. 2. Paket yang tujuannya di luar jaringan lokal diteruskan lewat gateway (biasanya router). 3. Switch dan hub hanya menghubungkan perangkat di dalam satu jaringan yang sama." },
    { q: "Dibanding IPv4, keunggulan utama IPv6 adalah …", options: ["Ruang alamat jauh lebih besar (128 bit) sehingga tidak cepat habis", "Ditulis dengan angka desimal saja", "Hanya untuk jaringan kabel", "Tidak butuh router"], answer: 0, solution: "1. IPv6 memakai alamat 128 bit sehingga jumlah alamatnya astronomis. 2. Ini mengatasi kelangkaan alamat IPv4 yang hanya 32 bit. 3. Penulisan IPv6 memakai heksadesimal yang dipisah tanda titik dua." },
    { q: "Untuk menghubungkan dua gedung yang berjarak jauh dengan kecepatan sangat tinggi, media transmisi yang paling tepat adalah …", options: ["Kabel UTP biasa", "Kabel serat optik (fiber optic)", "Kabel listrik", "Bluetooth"], answer: 1, solution: "1. Serat optik mengirim data sebagai cahaya sehingga sangat cepat dan tahan gangguan elektromagnetik. 2. Jangkauannya bisa puluhan kilometer tanpa penguat. 3. UTP terbatas sekitar 100 meter dan Bluetooth hanya untuk jarak sangat dekat." },
    { q: "Saat mencari WiFi di HP, daftar nama jaringan nirkabel yang muncul (misalnya WIFI_Sekolah) disebut …", options: ["Password", "IP address", "MAC address", "SSID"], answer: 3, solution: "1. SSID (Service Set Identifier) adalah nama identitas sebuah jaringan nirkabel. 2. Nama inilah yang disiarkan access point dan dipilih pengguna untuk terhubung. 3. Password adalah kunci masuknya, bukan namanya." },
    { q: "Paket internet tertulis berkecepatan 100 Mbps. Arti angka tersebut adalah …", options: ["Jumlah perangkat yang bisa terhubung", "Kapasitas maksimum transfer data 100 megabit per detik", "Jarak jangkauan sinyal", "Kuota 100 MB per bulan"], answer: 1, solution: "1. Mbps berarti megabit per detik, satuan kecepatan transfer data. 2. Angka ini adalah kapasitas maksimum (bandwidth), kecepatan nyata bisa lebih rendah. 3. Perhatikan huruf b kecil: megabit, bukan megabyte (MB)." },
    { q: "Pada alamat https://sekolah.sch.id/profil, bagian yang menunjukkan nama domain adalah …", options: ["://", "sekolah.sch.id", "https", "/profil"], answer: 1, solution: "1. Struktur URL: protokol://domain/jalur. 2. https adalah protokol, sedangkan /profil adalah jalur halaman. 3. Maka nama domainnya adalah sekolah.sch.id." },
    { q: "Dalam komunikasi web, peran browser di HP siswa dan server web sekolah berturut-turut adalah …", options: ["Client dan server", "Keduanya server", "Server dan client", "Router dan switch"], answer: 0, solution: "1. Client adalah pihak yang meminta layanan, sedangkan server adalah pihak yang melayani. 2. Browser meminta halaman (client), server web mengirimkan halaman (server). 3. Router dan switch adalah perangkat jaringan, bukan peran komunikasi web." },
    { q: "Protokol yang digunakan untuk MENGIRIM email dari aplikasi ke server email adalah …", options: ["IMAP", "SMTP", "POP3", "FTP"], answer: 1, solution: "1. SMTP (Simple Mail Transfer Protocol) bertugas mengirim email keluar. 2. POP3 dan IMAP dipakai untuk mengambil/membaca email dari server. 3. FTP adalah protokol transfer file, bukan email." },
    { q: "Fungsi utama firewall pada jaringan komputer adalah …", options: ["Menambah jumlah komputer", "Mendinginkan ruangan server", "Mempercepat unduhan", "Menyaring lalu lintas data yang masuk dan keluar berdasarkan aturan keamanan"], answer: 3, solution: "1. Firewall memeriksa setiap paket data yang lewat. 2. Paket yang mencurigakan atau dilarang aturannya akan diblokir. 3. Ia adalah garis pertahanan pertama, bukan alat penambah kecepatan." },
    { q: "Alamat IP 10.25.8.40 jika dilihat dari jenisnya termasuk alamat …", options: ["Multicast", "Publik kelas C", "Broadcast", "Privat kelas A"], answer: 3, solution: "1. Rentang 10.x.x.x dicadangkan untuk alamat privat kelas A. 2. Alamat ini hanya dipakai di jaringan lokal dan tidak dirutekan di internet. 3. Alamat broadcast selalu diakhiri oktet 255 pada bagian host." },
    { q: "Perbedaan utama virus komputer dan worm dalam cara menyebar adalah …", options: ["Virus menyebar lewat jaringan sedangkan worm lewat flashdisk", "Worm selalu lebih merusak daripada virus", "Keduanya tidak bisa menyebar tanpa koneksi internet", "Virus menempel pada program inang dan butuh aksi pengguna, sedangkan worm menyebar mandiri lewat jaringan"], answer: 3, solution: "1. Virus tidak bisa aktif sendiri: ia menempel pada file program dan menunggu pengguna menjalankannya. 2. Worm bersifat mandiri: menggandakan diri dan berpindah lewat jaringan tanpa bantuan pengguna. 3. Media penyebar (flashdisk atau jaringan) bisa dipakai keduanya, jadi bukan pembeda utama." },
    { q: "Jenis malware yang diam-diam merekam aktivitas pengguna, misalnya tombol keyboard yang ditekan, untuk mencuri data disebut …", options: ["Firewall", "Adware", "Keylogger", "Botnet"], answer: 2, solution: "1. Keylogger mencatat setiap ketikan, termasuk username dan password, lalu mengirimnya ke penyerang. 2. Ia termasuk keluarga spyware karena bekerja diam-diam. 3. Firewall justru pelindung jaringan, sedangkan adware hanya menampilkan iklan." },
    { q: "Malware yang membanjiri layar dengan iklan pop-up dan dapat mengarahkan browser ke situs berbahaya disebut …", options: ["Ransomware", "Rootkit", "Worm", "Adware"], answer: 3, solution: "1. Adware (advertising software) jahat menampilkan iklan agresif yang sulit ditutup. 2. Iklan tersebut sering menjadi pintu masuk malware lain saat diklik. 3. Ransomware mengunci data, rootkit bersembunyi di sistem, dan worm menyebar mandiri." },
    { q: "Celah tersembunyi yang dipasang malware agar penyerang bisa masuk kembali ke komputer korban kapan saja disebut …", options: ["Firewall", "Antivirus", "Backdoor", "Sandbox"], answer: 2, solution: "1. Backdoor artinya pintu belakang: akses rahasia yang tidak diketahui pemilik komputer. 2. Setelah malware masuk sekali, backdoor memastikan penyerang bisa kembali kapan pun. 3. Firewall, antivirus, dan sandbox justru alat pertahanan, bukan celah." },
    { q: "Malware yang bersembunyi sangat dalam di sistem operasi sehingga sulit dideteksi dan memberi kendali penuh ke penyerang disebut …", options: ["Adware", "Spam", "Cookie", "Rootkit"], answer: 3, solution: "1. Rootkit menanamkan diri di level terdalam sistem, bahkan sebelum antivirus berjalan. 2. Karena itu ia bisa menyembunyikan file dan proses jahat dari pemindaian. 3. Adware hanya beriklan, spam adalah pesan massal, dan cookie adalah data penjelajah biasa." },
    { q: "Sekelompok komputer yang terinfeksi lalu dikendalikan penyerang dari jauh untuk melancarkan serangan massal disebut …", options: ["Firewall", "Proxy", "Botnet", "VPN"], answer: 2, solution: "1. Tiap komputer korban menjadi 'bot' (robot) yang patuh pada perintah pengendali. 2. Ribuan bot yang terhubung membentuk 'net' (jaringan): inilah botnet. 3. Botnet biasa dipakai untuk serangan DDoS atau mengirim spam massal." },
    { q: "Serangan DDoS (Distributed Denial of Service) bertujuan …", options: ["Mencuri password pengguna", "Mengenkripsi data korban", "Membuat layanan lumpuh dengan membanjirinya trafik palsu", "Menyadap percakapan telepon"], answer: 2, solution: "1. DDoS membanjiri server target dengan permintaan palsu dalam jumlah raksasa. 2. Server kewalahan melayani trafik palsu sehingga pengguna asli tidak bisa masuk (denial of service). 3. Kata 'distributed' berarti serangan datang dari banyak sumber sekaligus, biasanya botnet." },
    { q: "Pada serangan man-in-the-middle, penyerang …", options: ["Mengirim email palsu yang mengaku dari bank", "Menebak password dengan mencoba semua kombinasi", "Menyusup di antara komunikasi dua pihak untuk menyadap atau mengubah data yang lewat", "Mengunci file korban dengan enkripsi"], answer: 2, solution: "1. Penyerang memosisikan diri 'di tengah' jalur komunikasi, misalnya di WiFi publik. 2. Data yang lewat bisa dibaca atau bahkan diubah tanpa disadari kedua pihak. 3. Pilihan lain adalah phishing, brute force, dan ransomware, bukan man-in-the-middle." },
    { q: "Serangan brute force terhadap sebuah password bekerja dengan cara …", options: ["Meminta password langsung kepada korban lewat telepon", "Menyadap sinyal WiFi publik", "Menyalin sidik jari korban", "Mencoba semua kemungkinan kombinasi karakter sampai menemukan yang benar"], answer: 3, solution: "1. Brute force artinya 'kekerasan': mencoba a, b, … aa, ab, sampai cocok. 2. Password pendek dan sederhana bisa jebol dalam hitungan detik dengan cara ini. 3. Inilah alasan password harus panjang dan kompleks." },
    { q: "Dictionary attack adalah serangan menebak password dengan …", options: ["Mencoba daftar kata umum dan password yang sering dipakai", "Mengacak seluruh alfabet satu per satu", "Membobol kamus cetak di perpustakaan", "Menerjemahkan password ke bahasa lain"], answer: 0, solution: "1. Penyerang memakai 'kamus' berisi jutaan kata umum dan password bocor seperti 'qwerty123'. 2. Cara ini jauh lebih cepat daripada brute force untuk password yang bisa ditebak. 3. Password acak yang panjang tidak ada di kamus sehingga aman dari serangan ini." },
    { q: "SQL injection adalah serangan yang …", options: ["Menyuntikkan vaksin ke dalam komputer", "Menyuntikkan kode berbahaya lewat kolom formulir situs agar basis data membocorkan atau merusak data", "Menyetrum kabel jaringan dengan listrik", "Memasukkan virus lewat colokan USB"], answer: 1, solution: "1. Formulir login atau pencarian yang tidak divalidasi bisa disisipi perintah SQL jahat. 2. Perintah itu dijalankan basis data sehingga data bisa dicuri, diubah, atau dihapus. 3. Pencegahannya: validasi input dan memakai prepared statement." },
    { q: "Celah keamanan zero-day disebut demikian karena …", options: ["Serangannya hanya berlangsung nol detik", "Celahnya hanya muncul tiap tanggal 1", "Penyerang memakai nol komputer", "Belum ada tambalan saat celah mulai dieksploitasi sehingga pengembang tidak punya waktu bersiap"], answer: 3, solution: "1. Zero-day berarti pengembang baru tahu celah pada 'hari ke-nol', saat serangan sudah terjadi. 2. Karena belum ada patch, pengguna tidak punya pertahanan resmi. 3. Celah ini sangat berharga dan sering dipakai dalam serangan siber tingkat tinggi." },
    { q: "Spear phishing berbeda dari phishing biasa karena …", options: ["Menggunakan gambar tombak sebagai logo", "Hanya menyerang para nelayan", "Dikirim lewat surat pos", "Menargetkan orang atau organisasi tertentu dengan pesan yang dipersonalisasi"], answer: 3, solution: "1. Phishing biasa disebar massal seperti menebar jala, sedangkan spear phishing seperti berburu dengan tombak: satu target. 2. Pesan dibuat personal (menyebut nama, jabatan, atau proyek korban) sehingga lebih meyakinkan. 3. Serangan ini sering mengincar karyawan perusahaan atau pejabat." },
    { q: "Pesan SMS yang mengaku dari jasa kurir paket dan meminta korban mengklik tautan berbahaya adalah contoh …", options: ["Smishing", "Vishing", "Pharming", "Whaling"], answer: 0, solution: "1. Smishing = phishing lewat SMS (gabungan kata SMS dan phishing). 2. Vishing memakai panggilan suara, pharming membelokkan alamat situs, dan whaling menargetkan pimpinan perusahaan. 3. Tautan dalam SMS semacam itu jangan diklik; cek status paket lewat aplikasi resmi." },
    { q: "Perbedaan utama enkripsi simetris dan asimetris adalah …", options: ["Simetris memakai satu kunci yang sama untuk mengenkripsi dan mendekripsi, sedangkan asimetris memakai pasangan kunci publik dan kunci privat", "Simetris hanya untuk teks dan asimetris hanya untuk gambar", "Asimetris selalu lebih cepat daripada simetris", "Simetris tidak memakai kunci sama sekali"], answer: 0, solution: "1. Enkripsi simetris ibarat gembok dan anak kunci yang sama dipakai berdua. 2. Enkripsi asimetris memakai kunci publik (boleh disebar) dan kunci privat (rahasia). 3. Simetris lebih cepat sehingga dipakai untuk data besar, sedangkan asimetris dipakai untuk bertukar kunci." },
    { q: "Dalam enkripsi asimetris, jika Andi ingin mengirim pesan rahasia kepada Budi, ia mengenkripsi pesan memakai …", options: ["Kunci publik milik Budi", "Kunci privat milik Andi", "Kunci publik milik Andi", "Kunci privat milik Budi"], answer: 0, solution: "1. Kunci publik boleh diketahui siapa saja, termasuk Andi. 2. Pesan yang dikunci dengan kunci publik Budi hanya bisa dibuka oleh kunci privat Budi. 3. Kunci privat tidak boleh dibagikan ke siapa pun, termasuk Andi." },
    { q: "Tanda tangan digital memastikan penerima bahwa pesan …", options: ["Dikirim dengan sangat cepat", "Berukuran file sangat kecil", "Gratis biaya pengiriman", "Benar-benar berasal dari pengirim yang diklaim dan tidak diubah selama perjalanan"], answer: 3, solution: "1. Tanda tangan digital dibuat dengan kunci privat pengirim sehingga membuktikan keaslian. 2. Jika isi pesan diubah di tengah jalan, verifikasi tanda tangan akan gagal. 3. Ini dipakai pada dokumen resmi elektronik dan pembaruan perangkat lunak." },
    { q: "Fungsi hash dalam keamanan siber dipakai terutama untuk …", options: ["Mempercepat koneksi internet", "Memverifikasi keutuhan data dan menyimpan password tanpa menyimpan teks aslinya", "Mengompres foto agar ukurannya kecil", "Membuat password mudah diingat"], answer: 1, solution: "1. Hash mengubah data menjadi kode unik berpanjang tetap; perubahan satu huruf saja mengubah hasilnya total. 2. Situs menyimpan hash password, bukan password aslinya, sehingga bocornya basis data tidak langsung membocorkan password. 3. Hash juga dipakai memastikan file unduhan tidak rusak atau dimodifikasi." },
    { q: "Sifat penting fungsi hash kriptografis adalah …", options: ["Bisa dibalik dengan mudah memakai kalkulator", "Hasilnya selalu sama panjang dengan inputnya", "Satu arah: mudah menghitung hash dari data, tetapi praktis mustahil mengembalikan data asli dari hash-nya", "Dua input berbeda tidak mungkin menghasilkan hash yang sama"], answer: 2, solution: "1. Sifat satu arah (one-way) membuat hash aman untuk menyimpan password. 2. Panjang hash selalu tetap berapa pun ukuran inputnya. 3. Secara teori tabrakan (collision) mungkin terjadi, tetapi pada hash modern praktis tidak dapat ditemukan." },
    { q: "Huruf S pada HTTPS menunjukkan bahwa …", options: ["Data antara browser dan situs dienkripsi sehingga sulit disadap", "Situs tersebut pasti bebas dari virus", "Situs tersebut milik pemerintah", "Situs tersebut memuat sangat cepat"], answer: 0, solution: "1. S = Secure: komunikasi diamankan dengan enkripsi TLS. 2. Pihak yang menyadap di tengah jalan hanya melihat kode acak. 3. Namun HTTPS tidak menjamin situsnya jujur; situs phishing pun bisa memakai HTTPS." },
    { q: "Langkah paling tepat saat komputer terkena ransomware adalah …", options: ["Segera membayar tebusan agar data kembali", "Menghapus antivirus supaya tidak bentrok", "Membiarkan komputer tetap menyala dan terhubung internet", "Memutus koneksi jaringan, tidak membayar tebusan, dan memulihkan data dari cadangan (backup)"], answer: 3, solution: "1. Membayar tebusan tidak menjamin data kembali dan justru mendanai kejahatan. 2. Putuskan jaringan agar ransomware tidak menyebar ke perangkat lain. 3. Pulihkan data dari backup bersih, lalu laporkan ke pihak berwenang." },
    { q: "Cryptojacking adalah penyalahgunaan komputer korban untuk …", options: ["Menambang aset kripto tanpa sepengetahuan pemiliknya", "Menyimpan foto-foto korban", "Mencetak uang palsu", "Membuat akun media sosial palsu"], answer: 0, solution: "1. Penyerang menyusupkan program penambang (miner) yang memakai CPU korban. 2. Korban hanya merasakan komputer melambat dan listrik membengkak. 3. Semua hasil tambang masuk ke kantong penyerang." },
    { q: "Serangan evil twin dilakukan dengan …", options: ["Membuat hotspot WiFi palsu bernama mirip WiFi asli untuk menjebak pengguna agar terhubung lalu datanya disadap", "Menggandakan kartu SIM korban", "Menyalin wajah korban dengan AI", "Membuat akun kembar di media sosial"], answer: 0, solution: "1. Penyerang membuat WiFi 'Kafe_Gratis' padahal yang asli 'Kafe Gratis'. 2. Korban yang terhubung melewatkan seluruh datanya lewat perangkat penyerang. 3. Selalu pastikan nama WiFi persis dan hindari transaksi penting di WiFi publik." },
    { q: "Packet sniffing adalah teknik …", options: ["Mengirim paket data lebih cepat ke tujuan", "Memfilter email spam dari kotak masuk", "Mengompres paket data agar hemat kuota", "Menangkap dan membaca paket data yang lewat di jaringan, berbahaya jika datanya tidak terenkripsi"], answer: 3, solution: "1. Sniffer 'mengendus' paket yang lewat, misalnya di jaringan yang sama. 2. Jika data tidak terenkripsi, username dan password bisa terbaca jelas. 3. Enkripsi seperti HTTPS dan VPN membuat hasil sadapan tidak berguna." },
    { q: "Frasa sandi (passphrase) seperti 'kuda-terbang-makan-nasi-7!' dianggap kuat karena …", options: ["Mengandung nama hewan peliharaan", "Panjang dan terdiri dari kata acak sehingga sulit ditebak tetapi mudah diingat pemiliknya", "Ditulis dengan huruf kapital semua", "Sama dengan nama pengguna"], answer: 1, solution: "1. Panjang adalah faktor terkuat: tiap karakter tambahan melipatgandakan kombinasi tebakan. 2. Kata acak tidak ada di kamus sehingga tahan terhadap dictionary attack. 3. Kalimat bermakna mudah diingat manusia tetapi sulit ditebak mesin." },
    { q: "Keuntungan utama memakai pengelola kata sandi (password manager) adalah …", options: ["Pengguna cukup mengingat satu kata sandi utama, sisanya dibuat acak dan disimpan aman", "Password bisa dibagikan ke semua orang", "Tidak perlu lagi memakai password", "Komputer menjadi kebal terhadap virus"], answer: 0, solution: "1. Manusia buruk mengingat banyak password acak, sehingga cenderung memakai ulang password lemah. 2. Password manager membuatkan password unik yang panjang untuk tiap akun. 3. Cukup lindungi satu kata sandi utama yang kuat plus 2FA." },
    { q: "Mengapa setiap akun sebaiknya memakai password yang berbeda? …", options: ["Agar mudah dihafal", "Karena situs mewajibkannya", "Supaya jika satu password bocor, akun lain tetap aman", "Agar terlihat keren"], answer: 2, solution: "1. Kebocoran data satu situs membuat password korban beredar di internet. 2. Penyerang mencoba password bocor itu ke situs lain (credential stuffing). 3. Password unik menghentikan serangan berantai tersebut." },
    { q: "Di antara metode verifikasi kedua berikut, yang paling aman untuk 2FA adalah …", options: ["Kode OTP lewat SMS", "Pertanyaan nama ibu kandung", "Mengingat password yang lebih panjang", "Aplikasi autentikator atau kunci keamanan fisik"], answer: 3, solution: "1. SMS bisa dibajak lewat SIM swap sehingga kode OTP jatuh ke penyerang. 2. Jawaban pertanyaan keamanan mudah ditemukan di media sosial. 3. Aplikasi autentikator dan kunci fisik tidak bisa disadap dari jarak jauh." },
    { q: "MFA (Multi-Factor Authentication) disebut multi-faktor karena …", options: ["Memakai banyak password sekaligus", "Login harus diulang berkali-kali", "Memakai banyak perangkat sekaligus", "Memakai lebih dari satu bukti identitas dari kategori berbeda, misalnya yang diketahui ditambah yang dimiliki"], answer: 3, solution: "1. Faktor itu kategorinya: sesuatu yang diketahui (password), dimiliki (HP), atau melekat (sidik jari). 2. Dua password tetap satu faktor, sehingga tidak disebut MFA. 3. Kombinasi kategori berbeda jauh lebih sulit ditembus." },
    { q: "Aturan 3-2-1 dalam pencadangan data berarti …", options: ["Menyimpan 3 salinan data, di 2 media berbeda, dengan 1 salinan di lokasi berbeda", "Backup 3 kali sehari, 2 kali seminggu, 1 kali sebulan", "Menyimpan 3 password, 2 akun, dan 1 HP", "Menghapus data 3 kali agar bersih"], answer: 0, solution: "1. Tiga salinan melindungi dari kerusakan satu salinan. 2. Dua media berbeda melindungi dari kegagalan satu jenis media. 3. Satu salinan di lokasi berbeda melindungi dari bencana seperti kebakaran." },
    { q: "Salah satu salinan backup sebaiknya disimpan offline (terputus dari jaringan) karena …", options: ["Supaya hemat listrik", "Agar tidak bisa dibuka oleh pemiliknya", "Karena koneksi internet lambat", "Agar tidak ikut terenkripsi saat ransomware menyerang"], answer: 3, solution: "1. Ransomware mengenkripsi semua drive yang terhubung, termasuk backup online. 2. Salinan offline (misalnya hard disk eksternal yang dicabut) tidak bisa dijangkau malware. 3. Inilah benteng terakhir saat semua salinan online ikut terkunci." },
    { q: "Memperbarui (update) sistem operasi dan aplikasi secara rutin penting karena …", options: ["Membuat tampilan selalu berubah-ubah", "Update menambah virus baru", "Update memperlambat HP", "Update menutup celah keamanan yang sudah ditemukan"], answer: 3, solution: "1. Setiap celah yang ditemukan peretas juga diketahui pengembang. 2. Patch menambal celah itu sebelum dieksploitasi. 3. Menunda update berarti membiarkan pintu yang sudah diketahui terbuka." },
    { q: "Aplikasi senter yang meminta izin akses kontak dan lokasi sebaiknya …", options: ["Diberi semua izin agar tidak error", "Dipasang lalu dibiarkan begitu saja", "Diberi ulasan bintang 5 terlebih dahulu", "Ditolak izinnya atau tidak dipasang, karena izin tersebut tidak wajar untuk fungsinya"], answer: 3, solution: "1. Izin harus sesuai fungsi: senter hanya butuh kamera (lampu flash). 2. Izin kontak dan lokasi mengisyaratkan pengumpulan data untuk iklan atau hal jahat. 3. Di Android dan iOS izin bisa ditolak satu per satu." },
    { q: "Prinsip 'hak akses seminimal mungkin' (least privilege) artinya …", options: ["Semua pengguna dijadikan administrator", "Izin diberikan seluas-luasnya", "Tidak ada yang boleh memakai komputer", "Pengguna dan aplikasi hanya diberi izin sesuai kebutuhan kerjanya, tidak lebih"], answer: 3, solution: "1. Akun biasa tidak butuh hak admin; aplikasi catatan tidak butuh akses kamera. 2. Jika akun diretas, kerusakan terbatas pada izin yang dimilikinya. 3. Prinsip ini dipakai di perusahaan, HP, hingga sistem operasi." },
    { q: "Risiko terbesar memakai WiFi publik gratis tanpa pengaman adalah …", options: ["Data yang dikirim bisa disadap pihak lain di jaringan yang sama", "Kuota internet cepat habis", "HP menjadi panas", "Baterai cepat penuh"], answer: 0, solution: "1. Di WiFi publik, semua perangkat berada di satu jaringan yang sama. 2. Penyerang bisa memakai sniffer atau serangan man-in-the-middle. 3. Hindari login bank atau gunakan VPN saat terpaksa memakai WiFi publik." },
    { q: "VPN membantu keamanan saat memakai jaringan publik dengan cara …", options: ["Mempercepat WiFi publik", "Menyembunyikan HP secara fisik", "Mengenkripsi seluruh lalu lintas internet pengguna sehingga sulit disadap", "Menambah kuota internet gratis"], answer: 2, solution: "1. VPN membuat 'terowongan' terenkripsi antara perangkat dan server VPN. 2. Pihak di jaringan publik hanya melihat kode acak. 3. VPN tidak membuat internet gratis atau lebih cepat." },
    { q: "Mengunci layar HP dengan PIN atau sidik jari penting karena …", options: ["Membuat HP terlihat mahal", "Menghemat baterai", "Mencegah orang lain membuka data jika HP hilang atau dipinjam", "Mempercepat prosesor"], answer: 2, solution: "1. HP berisi foto, chat, email, dan akses mobile banking. 2. Tanpa kunci layar, siapa pun yang memegang HP bisa membuka semuanya. 3. Biometrik plus PIN adalah kombinasi praktis dan aman." },
    { q: "Sebelum mengklik tautan mencurigakan di email, langkah bijak adalah …", options: ["Langsung mengklik agar cepat selesai", "Meneruskan email ke semua kontak", "Mengarahkan kursor untuk melihat alamat asli tautan dan memastikan domainnya benar", "Mengunduh semua lampirannya dulu"], answer: 2, solution: "1. Teks tautan bisa menipu, misalnya tertulis 'bank-aman.com' padahal mengarah ke situs lain. 2. Arahkan kursor (atau tekan lama di HP) untuk melihat alamat aslinya. 3. Situs asli bank memakai domain resmi yang sudah dikenal." },
    { q: "Lampiran email berupa file 'tagihan.pdf.exe' sebaiknya …", options: ["Dibuka dua kali agar pasti", "Diteruskan ke teman", "Tidak dibuka dan emailnya dihapus atau dilaporkan, karena ekstensi ganda menyamarkan program berbahaya", "Dicetak lalu dibuka"], answer: 2, solution: "1. Windows menyembunyikan ekstensi asli sehingga file tampak seperti PDF. 2. Ekstensi terakhir .exe menunjukkan ia program yang bisa dieksekusi. 3. Ini trik klasik menyamarkan malware sebagai dokumen." },
    { q: "Penyerang menelepon korban sambil mengaku sebagai teknisi bank dan meminta kode OTP. Teknik ini disebut …", options: ["Social engineering (rekayasa sosial)", "Machine learning", "Cloud computing", "Data mining"], answer: 0, solution: "1. Social engineering mengeksploitasi kepercayaan manusia, bukan kelemahan teknis. 2. Pelaku memakai rasa panik atau hormat pada otoritas agar korban patuh. 3. Bank asli tidak pernah meminta OTP lewat telepon." },
    { q: "Kode OTP tidak boleh diberikan kepada siapa pun, termasuk yang mengaku petugas, karena …", options: ["OTP membuat pulsa berkurang", "OTP hanya untuk dikoleksi", "OTP adalah kunci kedua akun; memberikannya sama dengan menyerahkan akses akun", "OTP merusak HP"], answer: 2, solution: "1. OTP adalah faktor kedua yang membuktikan kepemilikan HP pemilik akun. 2. Penyerang yang punya username, password, dan OTP bisa mengambil alih akun penuh. 3. Petugas resmi tidak pernah meminta OTP." },
    { q: "Setelah memakai komputer umum seperti di warnet atau lab, hal penting yang harus dilakukan adalah …", options: ["Mematikan monitornya saja", "Logout dari semua akun dan menghapus riwayat atau jejak login", "Membiarkan akun tetap terbuka", "Menghapus program antivirus"], answer: 1, solution: "1. Browser komputer umum bisa menyimpan sesi login dan password. 2. Pengguna berikutnya bisa membuka akun yang tertinggal. 3. Logout plus hapus riwayat menutup celah tersebut." },
    { q: "Jika mendapat kabar bahwa layanan yang dipakai mengalami kebocoran data, langkah tepat adalah …", options: ["Mengabaikannya karena bukan salah pengguna", "Menghapus akun email", "Mengganti password akun tersebut dan akun lain yang memakai password sama, serta mengaktifkan 2FA", "Membeli HP baru"], answer: 2, solution: "1. Password yang bocor akan dicoba penyerang ke banyak situs. 2. Ganti password akun yang bocor dan semua akun yang memakai password sama. 3. Aktifkan 2FA agar akun tetap aman walau password bocor." },
    { q: "Mengunduh aplikasi sebaiknya dari toko aplikasi resmi karena …", options: ["Aplikasi di sana melewati pemeriksaan sehingga kecil kemungkinan disusupi malware", "Ukurannya selalu lebih kecil", "Selalu gratis", "Tidak membutuhkan internet"], answer: 0, solution: "1. Toko resmi memindai aplikasi dari malware sebelum diterbitkan. 2. File APK dari situs sembarangan mudah disisipi trojan. 3. Pemeriksaan bukan jaminan mutlak, tetapi risikonya jauh lebih kecil." },
    { q: "Risiko memakai software bajakan (crack) adalah …", options: ["Komputer menjadi lebih cepat", "Sering disusupi malware karena file instalasi dimodifikasi peretas", "Mendapat garansi resmi", "Tidak ada risiko sama sekali"], answer: 1, solution: "1. Crack menonaktifkan proteksi lisensi dengan mengubah file program. 2. Di sela modifikasi itu peretas mudah menyisipkan trojan atau miner. 3. Selain berbahaya, pemakaian software bajakan melanggar hak cipta." },
    { q: "Shoulder surfing adalah …", options: ["Olahraga selancar di pantai", "Tindakan mengintip layar atau keyboard orang lain untuk mencuri PIN atau password", "Salah satu jenis antivirus", "Teknik berenang gaya bebas"], answer: 1, solution: "1. Pelaku mengintip dari balik bahu saat korban mengetik PIN di ATM atau HP. 2. Serangan ini tidak butuh keahlian teknis sama sekali. 3. Tutupi tangan saat mengetik PIN dan waspada orang di sekitar." },
    { q: "Pertanyaan keamanan seperti 'nama hewan peliharaan' kurang aman sebagai pemulih akun karena …", options: ["Hewan peliharaan cepat mati", "Jawabannya mudah ditemukan di media sosial korban", "Terlalu sulit diingat", "Tidak bisa diketik di keyboard"], answer: 1, solution: "1. Banyak orang memajang nama hewan peliharaan di media sosial. 2. Penyerang tinggal menggulir profil untuk menemukan jawabannya. 3. Lebih aman memakai aplikasi autentikator atau kode pemulihan." },
    { q: "Jika akun media sosial diretas, langkah pertama yang tepat adalah …", options: ["Membuat akun baru lalu melupakan akun lama", "Mencoba memulihkan akun lewat fitur resmi, mengganti password, dan mengaktifkan 2FA", "Memaki peretas di kolom komentar", "Menunggu sampai peretas bosan"], answer: 1, solution: "1. Platform menyediakan alur pemulihan resmi lewat email atau nomor HP. 2. Setelah kembali, ganti password dan aktifkan 2FA agar tidak diretas lagi. 3. Periksa juga aplikasi pihak ketiga yang terhubung ke akun." },
    { q: "Supervised learning disebut 'terbimbing' karena …", options: ["Guru mengawasi komputer secara langsung", "Model belajar tanpa memakai data sama sekali", "Model dilatih memakai data yang sudah berlabel jawaban benar", "Manusia mengetik setiap hasil prediksi"], answer: 2, solution: "1. Data latih disertai 'kunci jawaban', misalnya foto beserta label kucing atau anjing. 2. Model belajar memetakan ciri foto ke label yang benar. 3. Setelah terlatih, ia menebak label untuk foto baru yang belum berlabel." },
    { q: "Unsupervised learning cocok dipakai untuk …", options: ["Memprediksi harga rumah dari data historis berlabel", "Menemukan pola atau kelompok tersembunyi dari data yang tidak berlabel", "Mengenali email spam dari contoh email berlabel", "Mendiagnosis penyakit dari data pasien berlabel"], answer: 1, solution: "1. Data tidak punya label sehingga model mencari struktur sendiri. 2. Contohnya mengelompokkan pelanggan berdasarkan pola belanja. 3. Tiga pilihan lain memakai data berlabel sehingga termasuk supervised learning." },
    { q: "Manakah berikut ini contoh supervised learning? …", options: ["Mengelompokkan pelanggan berdasarkan pola belanja tanpa kategori awal", "Mendeteksi anomali transaksi tanpa contoh penipuan", "Meringkas dokumen tanpa contoh ringkasan", "Memprediksi cuaca besok dari data cuaca historis yang berlabel"], answer: 3, solution: "1. Data cuaca historis berlabel (misalnya hujan atau cerah tiap harinya) menjadi guru bagi model. 2. Model belajar hubungan antara kondisi hari ini dan cuaca besok. 3. Tiga pilihan lain tidak memakai label sehingga termasuk unsupervised." },
    { q: "Memprediksi harga jual sebuah rumah termasuk tugas …", options: ["Regresi, karena jawabannya berupa angka kontinu", "Klasifikasi, karena jawabannya berupa kategori", "Clustering, karena mengelompokkan rumah", "Reinforcement, karena ada hadiah"], answer: 0, solution: "1. Regresi memprediksi nilai angka yang bersambung, misalnya harga atau suhu. 2. Klasifikasi memprediksi kategori, misalnya spam atau bukan spam. 3. Harga rumah bisa bernilai berapa saja sehingga termasuk regresi." },
    { q: "Menentukan email masuk kategori spam atau bukan termasuk tugas …", options: ["Regresi", "Klasifikasi", "Reduksi dimensi", "Generatif"], answer: 1, solution: "1. Jawabannya berupa kategori: spam atau bukan spam. 2. Model belajar dari contoh email berlabel lalu mengklasifikasikan email baru. 3. Regresi dipakai untuk memprediksi angka, bukan kategori." },
    { q: "Clustering (pengelompokan) termasuk jenis …", options: ["Supervised learning", "Unsupervised learning", "Reinforcement learning", "Deep copying"], answer: 1, solution: "1. Clustering mengelompokkan data tanpa diberi tahu kategorinya terlebih dahulu. 2. Contohnya membagi pelanggan menjadi beberapa segmen belanja. 3. Karena tidak memakai label, ia termasuk unsupervised learning." },
    { q: "Reinforcement learning melatih agen dengan cara …", options: ["Menyalin jawaban dari buku panduan", "Menghafal seluruh data latih", "Memberi hadiah saat tindakannya benar dan hukuman saat salah, melalui coba-coba", "Bertanya kepada manusia di setiap langkah"], answer: 2, solution: "1. Agen mencoba aksi lalu menerima reward atau punishment dari lingkungan. 2. Lama-kelamaan ia menemukan strategi yang memaksimalkan hadiah. 3. Cara ini dipakai pada AI pemain game dan robot." },
    { q: "Jika data uji ikut dipakai untuk melatih model, akibatnya …", options: ["Skor evaluasi terlihat bagus secara palsu dan tidak mencerminkan performa pada data baru", "Model menjadi lebih jujur", "Data latih menjadi lebih sedikit", "Komputer menjadi lebih cepat"], answer: 0, solution: "1. Model sudah 'mengintip' soal ujian sehingga nilainya tinggi semu. 2. Fenomena ini disebut kebocoran data (data leakage). 3. Saat dipakai di dunia nyata dengan data baru, performanya anjlok." },
    { q: "Overfitting terjadi ketika …", options: ["Model menghafal data latih termasuk noise-nya sehingga gagal pada data baru", "Model terlalu sederhana sehingga tidak menangkap pola data", "Data latih terlalu banyak dan beragam", "Model dilatih terlalu cepat"], answer: 0, solution: "1. Ibarat siswa menghafal kunci jawaban latihan tanpa memahami konsep. 2. Nilai latihannya sempurna, tetapi gagal saat soal ujian berbeda. 3. Lawannya adalah underfitting: model terlalu sederhana hingga gagal di mana-mana." },
    { q: "Underfitting adalah kondisi ketika …", options: ["Model terlalu sederhana atau kurang dilatih sehingga gagal menangkap pola, buruk di data latih maupun data baru", "Model terlalu cocok dengan data latih", "Model hanya dipakai untuk data uji", "Data latih bocor ke data uji"], answer: 0, solution: "1. Ibarat siswa yang belajar setengah-setengah: nilai latihan saja sudah jelek. 2. Penyebabnya bisa model terlalu sederhana atau latih terlalu singkat. 3. Solusinya: model lebih kompleks atau latih lebih lama." },
    { q: "Secara umum, menambah data latih yang berkualitas dan beragam akan …", options: ["Menjamin model 100 persen akurat", "Membuat model menghafal lebih cepat", "Membuat model lebih mampu mengenali pola umum dan mengurangi overfitting", "Menghapus kebutuhan akan data uji"], answer: 2, solution: "1. Data beragam memaksa model belajar pola umum, bukan menghafal contoh. 2. Ini menekan overfitting karena noise tiap contoh saling meniadakan. 3. Namun akurasi 100 persen tetap tidak dijamin dan data uji tetap diperlukan." },
    { q: "Sistem pengenal wajah yang sering salah mengenali orang berkulit gelap kemungkinan besar disebabkan …", options: ["Kamera yang terlalu canggih", "Bias data: data latih didominasi wajah berkulit terang", "Pengguna yang memakai topi", "Koneksi internet yang lambat"], answer: 1, solution: "1. Model hanya sebaik data yang melatihnya. 2. Jika contoh wajah berkulit gelap sedikit, model tidak belajar cirinya dengan baik. 3. Inilah bias data: ketidakseimbangan data latih melahirkan ketidakadilan." },
    { q: "Prinsip 'garbage in, garbage out' dalam machine learning berarti …", options: ["Komputer harus dibersihkan dari debu", "Data latih yang kotor atau bias menghasilkan model yang buruk", "Model membuang data setelah dipakai", "Sampah elektronik harus didaur ulang"], answer: 1, solution: "1. Data salah, tidak lengkap, atau bias akan dipelajari model apa adanya. 2. Model canggih pun tidak bisa memperbaiki data yang buruk. 3. Karena itu pembersihan dan pemeriksaan data adalah tahap penting." },
    { q: "AI generatif, misalnya chatbot dan generator gambar, bekerja dengan …", options: ["Menyalin jawaban dari internet kata per kata", "Mempelajari pola dari data latih lalu menghasilkan teks atau gambar baru yang mirip polanya", "Mengetik secara acak tanpa pola", "Merekam suara manusia lalu memutarnya ulang"], answer: 1, solution: "1. Model mempelajari distribusi pola bahasa atau visual dari jutaan contoh. 2. Saat diminta, ia menyusun keluaran baru mengikuti pola tersebut. 3. Hasilnya orisinal dalam susunan, tetapi gayanya meniru data latih." },
    { q: "Halusinasi AI (AI hallucination) adalah kondisi ketika …", options: ["AI melihat penampakan hantu", "Komputer mengeluarkan asap", "AI memberikan jawaban yang terdengar meyakinkan tetapi faktanya salah atau karangan", "AI menolak menjawab pertanyaan"], answer: 2, solution: "1. Model dirancang menghasilkan teks yang masuk akal, bukan teks yang benar. 2. Ia bisa mengarang nama, tanggal, atau kutipan dengan percaya diri. 3. Karena itu jawaban AI untuk fakta penting wajib diverifikasi." },
    { q: "Prompt engineering adalah keterampilan …", options: ["Merancang instruksi yang jelas dan spesifik agar AI menghasilkan jawaban yang diinginkan", "Memperbaiki mesin ketik yang rusak", "Membangun gedung pencakar langit", "Menulis kode bahasa assembly"], answer: 0, solution: "1. Prompt yang samar menghasilkan jawaban yang samar. 2. Prompt baik memberi konteks, format, dan batasan yang jelas. 3. Ini keterampilan praktis memakai AI, bukan membangun modelnya." },
    { q: "Berikut ini contoh penerapan computer vision adalah …", options: ["Chatbot yang menjawab pertanyaan pelanggan", "Sistem membuka kunci HP dengan wajah pemiliknya", "Aplikasi menerjemahkan teks Inggris ke Indonesia", "Sistem rekomendasi lagu"], answer: 1, solution: "1. Computer vision membuat komputer 'melihat' lewat analisis citra. 2. Face unlock memetakan ciri wajah lalu mencocokkannya. 3. Chatbot dan penerjemah termasuk NLP, sedangkan rekomendasi lagu memakai pola perilaku." },
    { q: "Cabang AI yang berfokus agar komputer memahami dan mengolah bahasa manusia disebut …", options: ["Computer vision", "Robotika", "Natural Language Processing (NLP)", "Jaringan komputer"], answer: 2, solution: "1. NLP menangani teks dan ucapan: terjemahan, chatbot, dan analisis sentimen. 2. Tantangannya: bahasa manusia penuh ambiguitas dan konteks. 3. Computer vision menangani gambar, robotika menangani gerakan fisik." },
    { q: "Deep learning disebut 'deep' karena …", options: ["Hanya bisa dipakai perusahaan besar", "Modelnya berukuran file sangat kecil", "Dilatih tanpa data sama sekali", "Memakai jaringan saraf dengan banyak lapisan tersembunyi"], answer: 3, solution: "1. Tiap lapisan mengekstrak ciri makin abstrak: dari garis, bentuk, hingga objek. 2. Kedalaman inilah yang membuatnya unggul pada gambar dan bahasa. 3. Konsekuensinya: butuh data besar dan komputasi berat." },
    { q: "AI yang ada saat ini, seperti asisten virtual dan penerjemah otomatis, tergolong …", options: ["AI lemah (narrow AI) karena hanya ahli pada tugas spesifik", "AI kuat (general AI) yang setara manusia", "Robot yang sudah hidup", "Kecerdasan dari luar angkasa"], answer: 0, solution: "1. Narrow AI hebat pada satu tugas tetapi tidak bisa mengerjakan hal di luar itu. 2. Asisten virtual tidak bisa menyetir mobil walau pintar menjawab. 3. AGI setara manusia masih bersifat hipotetis." },
    { q: "Mengapa pelabelan data oleh manusia masih penting dalam supervised learning? …", options: ["Karena komputer tidak bisa membaca", "Karena model belajar dari contoh yang benar; label yang salah membuat model belajar pola yang salah", "Karena label membuat ukuran file lebih kecil", "Karena manusia membutuhkan pekerjaan"], answer: 1, solution: "1. Label adalah 'kunci jawaban' tempat model belajar. 2. Label salah berarti model diajari hal yang keliru. 3. Kualitas label sering lebih menentukan daripada kecanggihan model." },
    { q: "Contoh penerapan AI yang membantu dokter adalah …", options: ["Menggantikan dokter sepenuhnya", "Menganalisis citra rontgen untuk mendeteksi tanda penyakit lebih dini", "Menulis resep tanpa diagnosis", "Menolak pasien yang datang"], answer: 1, solution: "1. Model dilatih pada ribuan citra berlabel sehingga peka pada pola halus. 2. Ia berperan sebagai asisten: dokter tetap pengambil keputusan. 3. AI membantu, bukan menggantikan, tenaga medis." },
    { q: "Dalam machine learning, 'fitur' (feature) adalah …", options: ["Tombol tambahan di dalam aplikasi", "Iklan yang muncul di aplikasi gratis", "Karakteristik terukur dari data yang dipakai model untuk belajar, misalnya luas tanah dan jumlah kamar saat memprediksi harga rumah", "Warna tema aplikasi"], answer: 2, solution: "1. Fitur adalah input yang 'dilihat' model, misalnya ukuran dan lokasi rumah. 2. Memilih fitur yang tepat (feature engineering) sangat memengaruhi akurasi. 3. Fitur yang tidak relevan justru mengacaukan pembelajaran." },
    { q: "Praktik umum membagi dataset menjadi data latih dan data uji bertujuan …", options: ["Menilai seberapa baik model bekerja pada data yang belum pernah dilihatnya", "Menghemat ruang penyimpanan", "Mempercepat pengetikan", "Menyembunyikan data dari pengguna"], answer: 0, solution: "1. Nilai pada data latih saja menipu karena model sudah menghafalnya. 2. Data uji yang terpisah mensimulasikan dunia nyata. 3. Selisih besar antara keduanya menandakan overfitting." },
    { q: "Ciri umum berita hoaks adalah …", options: ["Ditulis dengan bahasa baku dan mencantumkan sumber resmi", "Dimuat di situs berita ternama", "Judul provokatif, sumber tidak jelas, dan mendesak untuk segera disebarkan", "Disertai data statistik yang lengkap"], answer: 2, solution: "1. Hoaks memancing emosi agar dibagikan tanpa berpikir. 2. Sumbernya kabur: tanpa penulis jelas atau situs abal-abal. 3. Desakan 'sebarkan sebelum dihapus' adalah taktik klasiknya." },
    { q: "Untuk memverifikasi sebuah klaim yang sedang viral, cara yang tepat adalah …", options: ["Melihat seberapa viral kiriman tersebut", "Bertanya di kolom komentar", "Mengecek jumlah like-nya", "Memeriksanya di situs cek fakta atau media kredibel, bukan sekadar melihat jumlah yang membagikan"], answer: 3, solution: "1. Viral tidak berarti benar; hoaks justru dirancang untuk viral. 2. Situs cek fakta menelusuri sumber asli sebuah klaim. 3. Bandingkan dengan minimal dua media kredibel sebelum percaya." },
    { q: "Filter bubble di media sosial menyebabkan pengguna …", options: ["Terus-menerus hanya melihat konten yang sependapat dengannya sehingga wawasannya menyempit", "Melihat semua sudut pandang secara seimbang", "Tidak bisa membuka media sosial", "Kehabisan kuota lebih cepat"], answer: 0, solution: "1. Algoritma menyaring konten yang tidak sesuai minat pengguna. 2. Lama-kelamaan pengguna hidup dalam 'gelembung' pendapat sendiri. 3. Akibatnya sulit memahami sudut pandang berbeda dan mudah termakan hoaks." },
    { q: "Algoritma linimasa media sosial umumnya menampilkan konten yang …", options: ["Paling mendidik tanpa memandang minat", "Sesuai minat dan riwayat interaksi pengguna agar betah berlama-lama", "Dipilih acak tanpa pola tertentu", "Hanya berasal dari akun resmi pemerintah"], answer: 1, solution: "1. Tujuan bisnis platform adalah membuat pengguna betah (engagement). 2. Konten yang disukai dan sering diklik akan terus dimunculkan. 3. Inilah mesin di balik filter bubble." },
    { q: "Contoh jejak digital pasif adalah …", options: ["Unggahan foto di media sosial", "Komentar di kolom diskusi", "Riwayat lokasi dan pencarian yang terekam otomatis tanpa disadari pengguna", "Status yang ditulis sendiri"], answer: 2, solution: "1. Jejak aktif dibuat sadar: posting, komentar, dan unggahan. 2. Jejak pasif terkumpul diam-diam: lokasi, riwayat pencarian, dan log aplikasi. 3. Keduanya sama-sama membentuk profil digital seseorang." },
    { q: "Mengatur akun media sosial menjadi privat bermanfaat untuk …", options: ["Menambah jumlah follower", "Membuat akun kebal diretas", "Mempercepat koneksi internet", "Membatasi siapa saja yang bisa melihat unggahan dan data pribadi"], answer: 3, solution: "1. Akun privat hanya menampilkan konten ke pengikut yang disetujui. 2. Ini mengurangi risiko data dipanen orang asing atau penjahat siber. 3. Namun akun privat bukan jaminan mutlak; pengikut pun bisa menyebarkan ulang." },
    { q: "Membagikan boarding pass pesawat ke media sosial berbahaya karena …", options: ["Barcode-nya bisa dipindai orang lain untuk mengakses data penerbangan dan data pribadi penumpang", "Membuat teman-teman menjadi iri", "Melanggar aturan maskapai tentang berfoto", "Mengurangi nilai harga tiket"], answer: 0, solution: "1. Barcode boarding pass menyimpan kode booking, nama, dan jadwal penerbangan. 2. Orang asing bisa mengubah atau membatalkan penerbangan korban. 3. Aturannya: pamer boleh, tetapi sensor barcode dan kode booking." },
    { q: "Contoh data pribadi yang wajib dijaga kerahasiaannya adalah …", options: ["Judul film favorit", "NIK, nomor KK, dan data biometrik", "Warna kesukaan", "Tim olahraga favorit"], answer: 1, solution: "1. NIK dan nomor KK adalah identitas resmi yang bisa disalahgunakan untuk penipuan. 2. Data biometrik (wajah, sidik jari) tidak bisa diganti jika bocor. 3. Data favorit bersifat publik dan tidak sensitif." },
    { q: "Menurut UU ITE, menyebarkan tuduhan yang mencemarkan nama baik seseorang di media sosial dapat …", options: ["Dianggap kebebasan berpendapat tanpa batas", "Dibiarkan selama memakai akun anonim", "Dipidana karena termasuk pencemaran nama baik secara elektronik", "Hanya ditegur jika korbannya pejabat"], answer: 2, solution: "1. Kebebasan berpendapat dibatasi oleh hak orang lain. 2. UU ITE mengatur pencemaran nama baik dan fitnah di ruang digital. 3. Akun anonim pun bisa dilacak lewat jejak digital." },
    { q: "Menyebarkan berita bohong yang menimbulkan keonaran di masyarakat dapat dijerat UU ITE karena …", options: ["Hanya dilarang jika dibaca banyak orang", "Boleh selama niatnya bercanda", "Tidak diatur karena internet bebas aturan", "Termasuk penyebaran informasi bohong yang merugikan dan dilarang undang-undang"], answer: 3, solution: "1. UU ITE melarang penyebaran berita bohong yang menimbulkan kerusuhan. 2. Alasan 'bercanda' tidak menghapus akibat keonaran yang terjadi. 3. Internet bukan ruang tanpa hukum." },
    { q: "Membobol akun atau sistem milik orang lain tanpa izin melanggar UU ITE tentang …", options: ["Akses ilegal terhadap sistem elektronik", "Hak cipta lagu", "Pajak penggunaan internet", "Kecepatan koneksi"], answer: 0, solution: "1. Mengakses sistem tanpa hak adalah tindak pidana menurut UU ITE. 2. Termasuk di dalamnya meretas akun, menyadap, dan mencuri data. 3. Izin pemilik adalah batas tegasnya." },
    { q: "Prinsip 'THINK' sebelum mengunggah (True, Helpful, Inspiring, Necessary, Kind) mengajarkan agar …", options: ["Unggahan harus selalu panjang", "Setiap unggahan dipertimbangkan kebenaran dan manfaatnya bagi orang lain", "Berpikir membuat unggahan menjadi lambat", "Hanya boleh mengunggah hal-hal lucu"], answer: 1, solution: "1. Tanyakan: benarkah, membantu kah, menginspirasi kah, perlu kah, baik kah? 2. Satu unggahan buruk bisa merusak reputasi bertahun-tahun. 3. Prinsip ini melatih etika bermedia sosial sehari-hari." },
    { q: "Cyberbullying berbeda dari perundungan biasa karena …", options: ["Selalu dilakukan secara tatap muka", "Bisa terjadi kapan saja, tersebar luas dengan cepat, dan pelakunya bisa anonim", "Tidak pernah menimbulkan luka psikis", "Mudah dilupakan oleh korban"], answer: 1, solution: "1. Internet tidak mengenal jam istirahat: korban bisa diserang tengah malam. 2. Satu unggahan jahat bisa dilihat ribuan orang dalam sekejap. 3. Anonimitas membuat pelaku merasa aman dan semakin berani." },
    { q: "Langkah tepat jika menjadi korban perundungan siber adalah …", options: ["Membalas dengan perundungan yang lebih kejam", "Menghapus semua akun media sosial selamanya", "Menyebarkan identitas pelaku ke publik", "Menyimpan bukti, memblokir pelaku, dan melapor ke orang dewasa atau pihak berwenang"], answer: 3, solution: "1. Screenshot pesan jahat sebagai bukti sebelum dihapus pelaku. 2. Blokir agar serangan berhenti, lalu laporkan. 3. Membalas hanya memperkeruh dan bisa membuat korban ikut bersalah." },
    { q: "Mengunggah ulang video karya orang lain tanpa izin dan mengaku sebagai milik sendiri melanggar …", options: ["Hak cipta, yaitu hak eksklusif pencipta atas karyanya", "Hak untuk berlibur", "Hak untuk memilih", "Hak atas jalan raya"], answer: 0, solution: "1. Pencipta otomatis memegang hak cipta atas karyanya. 2. Mengunggah ulang tanpa izin melanggar hak penggandaan dan distribusi. 3. Mengaku sebagai pemilik menambah pelanggaran moral." },
    { q: "Lisensi Creative Commons pada sebuah karya digital berarti …", options: ["Karya bebas dipakai tanpa aturan apa pun", "Pencipta mengizinkan karyanya dipakai orang lain dengan syarat tertentu, misalnya mencantumkan kredit", "Karya dilarang dibuka oleh siapa pun", "Karya hanya boleh dilihat oleh penciptanya"], answer: 1, solution: "1. Creative Commons adalah jalan tengah antara hak cipta penuh dan domain publik. 2. Syarat umum: cantumkan nama pencipta (atribusi). 3. Varian lain bisa melarang pemakaian komersial atau karya turunan." },
    { q: "Menyalin tugas dari internet tanpa mencantumkan sumber termasuk …", options: ["Riset yang baik", "Kreativitas yang tinggi", "Plagiarisme, yaitu memakai karya orang lain seolah karya sendiri", "Kerja sama yang sehat"], answer: 2, solution: "1. Plagiarisme adalah pencurian intelektual. 2. Menyalin lalu parafrase tanpa sumber tetap plagiarisme. 3. Cara benar: kutip dan cantumkan sumbernya." },
    { q: "Mengutip sebagian kecil teks berhak cipta untuk tugas sekolah disertai sumber umumnya diperbolehkan karena …", options: ["Tugas sekolah bebas dari hukum", "Penulisnya pasti tidak keberatan", "Internet adalah milik bersama", "Termasuk penggunaan wajar untuk pendidikan, bukan pembajakan utuh"], answer: 3, solution: "1. Penggunaan wajar (fair use) memberi ruang untuk pendidikan dan kritik. 2. Syaratnya: sebagian kecil, tidak menggantikan karya asli, dan sumber dicantumkan. 3. Mengunggah ulang buku utuh jelas bukan penggunaan wajar." },
    { q: "Memakai software berbayar tanpa lisensi resmi (bajakan) selain berisiko malware juga …", options: ["Melanggar hak cipta pembuat software", "Dianjurkan untuk menghemat uang", "Legal selama untuk belajar", "Tidak ada konsekuensi hukumnya"], answer: 0, solution: "1. Software adalah karya berhak cipta seperti buku dan lagu. 2. Crack dan keygen adalah pembajakan. 3. Alternatif legal: software gratis atau versi pelajar resmi." },
    { q: "Tanda air (watermark) pada foto digital berfungsi untuk …", options: ["Membuat foto tahan terhadap air", "Menandai kepemilikan karya sehingga sulit diklaim orang lain", "Memperbesar ukuran file foto", "Menghapus metadata foto"], answer: 1, solution: "1. Watermark berupa logo atau teks samar milik pencipta. 2. Ia menyulitkan orang mengaku foto itu miliknya. 3. Ini perlindungan praktis, bukan pengganti hak cipta." },
    { q: "Banyak perusahaan memeriksa media sosial calon karyawan karena …", options: ["Ingin menambah jumlah teman", "Jejak digital mencerminkan karakter dan reputasi yang sulit disembunyikan", "Diwajibkan undang-undang ketenagakerjaan", "Sekadar iseng mengisi waktu"], answer: 1, solution: "1. Unggahan lama mencerminkan sikap dan nilai seseorang. 2. Perusahaan menilai risiko reputasi calon karyawan. 3. Kelola media sosial seolah CV publik." },
    { q: "Doxxing adalah tindakan …", options: ["Bermain game menembak secara online", "Menghapus dokumen-dokumen lama", "Menyebarluaskan data pribadi seseorang seperti alamat dan nomor HP tanpa izin untuk menjahatinya", "Menggandakan kunci rumah"], answer: 2, solution: "1. Doxxing membongkar identitas dan data pribadi target ke publik. 2. Tujuannya mengintimidasi atau memancing serangan lanjutan. 3. Ini melanggar privasi dan dapat dijerat hukum." },
    { q: "Sharenting adalah kebiasaan orang tua yang …", options: ["Berbagi mainan dengan tetangga", "Mengajarkan anak berbagi makanan", "Berbagi koneksi WiFi", "Berbagi terlalu banyak foto dan data pribadi anak di media sosial hingga berisiko bagi privasi anak"], answer: 3, solution: "1. Foto anak lengkap dengan nama sekolah dan lokasi membentuk jejak digital anak. 2. Data itu bisa disalahgunakan orang tak bertanggung jawab. 3. Anak berhak atas privasinya, bahkan dari orang tuanya." },
  ]
};
